window.PREP_QUIZZES = {"start": {"title": "Start here", "description": "Shashank Singh | GenAI, Applied AI and Full Stack AI interviews", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-a970edc6cf83", "topic": "start", "lessonId": "start-7f98baedcf", "tag": "Continue from your previous preparation", "prompt": "What makes a strong system-design interview answer?", "options": ["Name as many cloud services as possible without a request flow.", "Promise zero errors and unlimited scale.", "Quote hypothetical performance as a measured result.", "Clarify constraints, sketch the flow, justify trade-offs and name evaluation measures."], "correct": 3, "explanation": "A design is defensible when its decisions follow stated constraints and can be evaluated. Explain failure handling and identify assumptions before claiming performance.", "technical": "Use a six-part sequence: requirements and constraints; data and trust boundaries; offline and online flow; alternatives; quality and reliability evaluation; rollout and failure recovery. Ask about workload shape, freshness, access rules, action risk, latency, data sensitivity and cost. Use explicit assumptions when the interviewer supplies no values.", "followups": [["What if I do not know a tool's exact flag?", "Explain the mechanism and the measurement you would make, then say the flag must be verified against the pinned version. Guessing syntax undermines a sound architectural explanation."], ["What if the interviewer insists on one best framework?", "State the requirement that drives your choice: simple deterministic pipeline, durable graph with human approval, or managed workflow. Compare operational cost and failure handling rather than treating a framework name as a design argument."]]}, {"id": "quiz-14748c31385c", "topic": "start", "lessonId": "start-da741cd8e8", "tag": "Continue from your previous preparation", "prompt": "How should you present an architecture you have designed but not deployed?", "options": ["State illustrative metrics as production results.", "Claim ownership of every service mentioned in an example.", "Avoid discussing assumptions or limitations.", "Label it as a proposed design and separate it from measured project evidence."], "correct": 3, "explanation": "Interview preparation should improve reasoning without inventing experience. Distinguish what you implemented, what you measured and what you would propose.", "technical": "Use three labels in your own notes: implemented and evidenced; resume-reported but evidence to collect; studied or proposed. For each implemented system record your role, dates, exact model/version, workload, data split, latency boundary and failure case. Keep private client data out of interview materials.", "followups": [["What if a resume line is broader than my direct role?", "State your specific contribution and the team's surrounding work. If the line is inaccurate, correct it before interviewing. These PDFs preserve your existing resumes and provide a verification checklist rather than silently rewriting them."], ["Can I memorize the spoken answers verbatim?", "Use them as structures. Interviewers vary constraints, so rehearse changing a requirement and revising the architecture. An answer you cannot adapt is fragile."]]}]}, "python": {"title": "Python", "description": "Language reasoning, concurrency, reliable data pipelines and practical coding", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-9648d66ddaf1", "topic": "python", "lessonId": "python-1093ebecd0", "tag": "Language fundamentals that interviewers probe", "prompt": "Why can def add(x, items=[]) share state across calls?", "options": ["The default list is created once when the function definition executes.", "Python copies every default argument on each call.", "Lists are immutable in function parameters.", "Garbage collection forbids lists in functions."], "correct": 0, "explanation": "The same default list object is reused. Use a None sentinel and create a list inside the function when independent state is intended.", "technical": "In def add(x, items=[]), append changes the same list on later calls. Use None and construct a list inside. A shallow copy duplicates the outer container but retains references to nested objects. A deep copy recursively copies supported objects, which can be expensive and inappropriate for connections or locks. Immutability is about the object, not whether a variable can be reassigned.", "followups": [["Is a tuple always deeply immutable?", "Its element references cannot be replaced, but a tuple can contain a mutable list. That list can still change. Hashability also depends on whether its contents are hashable."], ["Does assigning a list to another variable copy it?", "No. Both names refer to the same object. Use list(original) for a shallow copy and explicitly decide whether nested structures also need copying."]]}, {"id": "quiz-61ec5be8fdb3", "topic": "python", "lessonId": "python-bafd6c9008", "tag": "Concurrency and reliability", "prompt": "An async API performs a slow blocking network call directly on the event loop. What can happen?", "options": ["The async keyword automatically makes every library call nonblocking.", "The GIL guarantees unlimited parallel network clients.", "The call cannot fail because it is inside async def.", "Other coroutines on that loop can stall; use a suitable async client or bounded offload."], "correct": 3, "explanation": "Cooperative concurrency requires yielding operations. A blocking call prevents the event loop from scheduling other work until it returns.", "technical": "In ordinary GIL-enabled CPython, only one thread executes Python bytecode at a time, but I/O and many native extensions release the GIL. Free-threaded builds have different behavior and extension constraints; state your environment. Async functions cooperate at await points. CPU-heavy Python parsing inside async def blocks other requests unless offloaded. GPU concurrency is governed by the serving engine and memory, not by creating more Python coroutines.", "followups": [["Does async def make synchronous requests.get nonblocking?", "No. That call still blocks its thread. Use an async client or a carefully bounded thread offload, and configure timeouts and connection limits."], ["Why can 1,000 tasks be slower than 20?", "They can overwhelm rate limits, sockets, memory and queues. Bound concurrency and use admission control; the optimum depends on service time and bottlenecks."]]}, {"id": "quiz-9867adb7a0bc", "topic": "python", "lessonId": "python-6be08773b7", "tag": "Concurrency and reliability", "prompt": "What protects an async ingestion worker from launching 100,000 requests at once?", "options": ["Putting secrets into each exception message.", "A bounded worker pool/semaphore and a total cancellation/deadline policy.", "Creating every task immediately with no resource budget.", "Infinite retries without backoff."], "correct": 1, "explanation": "Bound in-flight work according to downstream capacity. Propagate cancellation, release resources and avoid collecting an unbounded number of pending tasks.", "technical": "In Python 3.11+, TaskGroup provides structured concurrency: a failing child typically cancels remaining siblings and failures are grouped. A semaphore bounds active work. A per-call timeout differs from a whole-request deadline. Pass the remaining budget downstream and decide whether partial results are acceptable. A semaphore alone does not bound the number of created pending tasks for millions of items.", "followups": [["Does cancelling an HTTP await undo a remote write?", "No. The remote system may already have committed it. Use an idempotency key and a status lookup to reconcile uncertain outcomes."], ["What if one failed document should not cancel the batch?", "Catch expected per-document errors inside the worker and return a typed success/failure record. Keep programming errors and systemic failures visible instead of catching everything indiscriminately."]]}]}, "llms": {"title": "LLMs & transformers", "description": "Definitions you can defend, tensor intuition and generation behavior", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-28aeb0ca1d7a", "topic": "llms", "lessonId": "llms-30bac90d15", "tag": "Numerical reasoning", "prompt": "With logits [2,1,0], increasing temperature from 1 to 2 changes the highest token probability approximately how?", "options": ["From 0.665 to 0.506; the distribution becomes flatter.", "From 0.665 to 0.867; it becomes sharper.", "It stays 0.665 because logits never change.", "It becomes exactly 1 and eliminates hallucination."], "correct": 0, "explanation": "Temperature changes how strongly a generator favors its highest-scoring next token. It changes sampling probabilities, not the model weights or the facts available to it. For the same logits [2,1,0], the leading token has probability about 66.5% at T=1, 50.6% at T=2 and 86.7% at T=0.5. Low temperature makes this particular choice more concentrated, but an incorrect high-logit token can still win.", "technical": "For logits z_i and positive temperature T, p_i = exp(z_i/T) / sum_j exp(z_j/T). Subtract max(z/T) before exponentiating for numerical stability. With a fixed vocabulary and finite logits, higher T flattens the distribution. T=0 is normally implemented as a greedy-decoding convention; directly dividing by zero is undefined. Provider support and interactions with other sampling controls vary.", "followups": [["Does temperature zero guarantee repeatable or correct answers?", "No. Greedy selection concerns decoding. Model updates, floating-point execution, ties, tools and changing context can alter outputs; correctness still needs evidence and evaluation."], ["When can a higher temperature help?", "It can diversify brainstorming candidates. Evaluate candidate quality and downstream selection instead of assuming diversity is accuracy. Use stronger constraints for deterministic business outputs."]]}, {"id": "quiz-351003a7b416", "topic": "llms", "lessonId": "llms-fad383eca2", "tag": "Numerical reasoning", "prompt": "For scores [0.7071,0] and values [10,0], [0,20], what is the approximate attention output?", "options": ["[1,0], because attention must return the query.", "[6.70,6.60], using softmax weights near [0.67,0.33].", "[10,20], because attention concatenates both values.", "[0.7071,0], because values are ignored."], "correct": 1, "explanation": "A query asks what information is useful, keys describe what each token offers, and values contain the information to mix. Attention compares the query with keys and forms a weighted average of values. The first key matches the query more strongly, so its value gets about 67% of the weight. The output is 0.6698*[10,0] + 0.3302*[0,20], not a selection of only one value. This toy calculation omits dropout, output projection and other heads.", "technical": "For one head, Q=XW_Q, K=XW_K and V=XW_V in self-attention. Compute scores QK^T/sqrt(d_k), apply any mask before row-wise softmax, then multiply by V. Cross-attention takes queries from a different stream than keys and values. Attention weights are input-dependent routing coefficients; they are not the trained W matrices.", "followups": [["Why divide by sqrt(d_k)?", "For components with roughly unit variance, an unscaled dot product's variance grows with d_k. Scaling helps avoid overly large scores that saturate softmax and weaken useful gradients."], ["Are Q, K and V always identical?", "No. They can start from the same token representations in self-attention but use distinct learned projections. Cross-attention uses different input streams, and architectures can share some projections deliberately."]]}, {"id": "quiz-1822f7847201", "topic": "llms", "lessonId": "llms-aa97356daa", "tag": "Numerical reasoning", "prompt": "With d_model=512 and 8 standard heads, what is each head's key dimension?", "options": ["4096, because dimensions multiply by head count.", "512 for each head, necessarily.", "8, because head count equals key width.", "64, assuming equal head widths."], "correct": 3, "explanation": "Each head examines a smaller representation of every token. The heads run side by side and their outputs are combined back into the model's hidden width. Eight heads of width 64 still cover a total width of 512; they do not make the model width 4096. A 512-by-512 projection has 262,144 weights. Count all four projections separately and clarify whether the architecture uses shared K/V heads.", "technical": "For batch B, sequence length n, model width d and h equal-size standard heads, Q,K,V after projection can be reshaped to [B,h,n,d/h]. The attention score tensor is [B,h,n,n]. Concatenation returns [B,n,d], followed by an output projection. Standard full-width Q,K,V and output matrices contain approximately 4*d*d weights, excluding biases. GQA and MQA change key/value projection and cache sizes.", "followups": [["What grows quadratically with sequence length?", "The dense attention score/probability structure has n-by-n interactions per head. Optimized kernels avoid materializing the full matrix but do not make ordinary dense attention interaction count linear."], ["Does increasing head count at fixed width always increase parameters?", "Not in standard full-width projections: the partitioning changes while the four d-by-d matrices remain. Other architectural choices and per-head overhead can change the result."]]}, {"id": "quiz-63e621399f1b", "topic": "llms", "lessonId": "llms-62296c9905", "tag": "Numerical reasoning", "prompt": "In the example with 32 layers, 4096 tokens and 8 KV heads of width 128 in FP16, raw KV storage is about what?", "options": ["512 MiB for batch size one.", "512 bytes regardless of token count.", "The entire parameter file size exactly.", "Zero because caching removes memory usage."], "correct": 0, "explanation": "During generation, a token must not see future tokens. The server processes the prompt first, then generates new tokens while reusing keys and values already computed for the prefix. The toy configuration above needs roughly 512 MiB for one request's raw KV entries. Doubling the sequence length doubles that estimate. GQA with eight KV heads can use less KV storage than 32 independent KV heads at the same head width.", "technical": "Causal masking adds negative infinity to disallowed attention scores before softmax. Prefill computes the prompt's representations and cache. Decode appends new token K/V entries and attends to permitted prefix positions. A rough cache footprint is 2*layers*batch*tokens*KV_heads*head_dim*bytes_per_element, excluding allocator overhead. Cache usage depends on actual serving architecture, not just model parameter count.", "followups": [["Does KV caching eliminate all compute for every generated token?", "No. Each new token still traverses the network and attends to the prefix. The cache avoids recomputing the historical keys/values; attention bandwidth and growing context still matter."], ["Can arbitrary prompts share a prefix cache?", "Only compatible, genuinely identical prefixes under the engine's rules. Enforce privacy/isolation and include model/adapter/version identity; similar-looking text is not sufficient."]]}, {"id": "quiz-fbec383557d0", "topic": "llms", "lessonId": "llms-3ae20dc5a4", "tag": "Numerical reasoning", "prompt": "For [0.60,0.25,0.10,0.05], which tokens does top-p=0.8 retain under the usual nucleus rule?", "options": ["The first two, whose cumulative probability is 0.85.", "All four because 0.8 exceeds every individual probability.", "Exactly 80% of vocabulary entries.", "Only the last token because it is least likely."], "correct": 0, "explanation": "Temperature reshapes scores. Top-k keeps a fixed number of high-ranked candidates; top-p keeps a smallest high-ranked prefix whose probability mass reaches a chosen threshold. For sorted probabilities [0.60,0.25,0.10,0.05], top-p=0.8 retains the first two tokens because their cumulative mass is 0.85. After renormalization their probabilities are about [0.706,0.294]. Top-k=3 would retain three candidates before any additional rules.", "technical": "Sampling implementations apply temperature and truncation in a particular order, then renormalize. Inspect the provider's semantics before deriving exact probabilities. Nucleus size varies by distribution. Increasing top-p permits a larger candidate set but does not itself train a more knowledgeable model. Simultaneously tuning several controls makes attribution difficult.", "followups": [["Would top-p=0.8 keep exactly 80% of the vocabulary?", "No. It is a probability-mass threshold, not a vocabulary percentage. A peaked distribution can cross it with one token."], ["Which control should you tune first?", "Hold the other controls fixed, choose one based on the task, and compare on a versioned evaluation set. Provider restrictions can determine which settings are available."]]}, {"id": "quiz-a3bd262c1cf4", "topic": "llms", "lessonId": "llms-e2d219c88e", "tag": "Numerical reasoning", "prompt": "For target probabilities 0.5 and 0.25 using natural logs, what is perplexity?", "options": ["Exactly 75% factual accuracy.", "Zero, because both probabilities are positive.", "About 2.83.", "Exactly 0.375, their arithmetic mean."], "correct": 2, "explanation": "Cross-entropy penalizes a model when it assigns low probability to the correct next token. Perplexity expresses average token uncertainty on an exponential scale. A model that predicts two target tokens with probabilities 0.5 and 0.25 has perplexity about 2.83 on this toy sequence. This says nothing about whether a generated financial claim is supported by a source; that needs a separate grounded task evaluation.", "technical": "For N evaluated target tokens, mean negative log-likelihood is -(1/N)*sum(log p(y_t|prefix)); perplexity is exp(mean NLL) when natural logarithms are used. Specify token masking, tokenizer, dataset and context. Lower perplexity on one distribution does not prove better factual accuracy, instruction following or tool safety, and scores across incompatible tokenizers are not directly comparable.", "followups": [["Why average logs rather than probabilities?", "Sequence likelihood multiplies conditional probabilities. Logs turn the product into a stable sum and penalize confidently low probabilities on the correct targets."], ["Can a fluent hallucination have low perplexity?", "Yes. Plausible language can be likely without being true for the user's case. Evaluate source support, correctness and abstention separately."]]}, {"id": "quiz-32ee016ed0c9", "topic": "llms", "lessonId": "llms-08f873fbf0", "tag": "Production decisions", "prompt": "A greedy decoder repeatedly quotes an expired policy. What is the best first repair?", "options": ["Raise temperature until a desired answer appears.", "Add GPU replicas without inspecting evidence.", "Declare temperature zero a factuality guarantee.", "Verify source applicability and the rendered context before changing sampling."], "correct": 3, "explanation": "Making the model less random does not give it missing facts or fix a misleading prompt. Trace whether the failure came from evidence, interpretation, reasoning or output handling. A refund bot says 30 days at T=0 because a stale 30-day policy dominates its context while the current policy says 14. Selecting greedily simply repeats the stale answer more consistently.", "technical": "Capture the exact model revision, prompt template, rendered context, token counts, retrieved IDs and output. Reproduce on a sanitized failing case. If evidence is absent, repair retrieval or abstain; if evidence is present, inspect truncation, conflicting instructions and constrained output handling. Test the repair on failure slices and a holdout before canary rollout.", "followups": [["Should you increase temperature until it says 14?", "No. That selects a lucky sample rather than fixing the causal failure. Repair the evidence/decision boundary and evaluate repeated runs as appropriate."], ["When would fine-tuning help?", "For repeatable behavior or domain task patterns with representative training data. Frequently changing factual policy is usually better supplied through governed retrieval or an authoritative API."]]}]}, "rag": {"title": "RAG & retrieval", "description": "BM25, TF-IDF, BM42, fusion, reranking and evidence-grounded answers", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-45d9cfa00916", "topic": "rag", "lessonId": "rag-4b157228c7", "tag": "Advanced architecture scenarios", "prompt": "A correct document's irrelevant introduction is retrieved for an exception question. What should you measure?", "options": ["Only the number of model parameters.", "Chunk/evidence-span recall and whether the required clause reaches the prompt.", "Only document filename match rate.", "Only whether top-k is larger than ten."], "correct": 1, "explanation": "A document match does not mean the exact evidence reached the model. Inspect the retrieved chunks and the assembled prompt, not just the file title. A cancellation question retrieves a 200-page policy's introduction but not its cancellation exception. Recover the relevant clause through better chunk boundaries, keyword/hybrid matching or focused section retrieval, then verify it survives prompt assembly.", "technical": "Evaluate chunk-level relevance, section hierarchy, exact terms, metadata filters, reranking and context packing. Try parent/adjacent or cross-reference expansion with a token budget when required evidence spans boundaries. Use labeled query-to-span examples and compare changes independently. Increasing k can improve recall while adding noise and burying the answer.", "followups": [["Could the reranker still fail?", "Yes. Its training/task fit, truncation and input formatting can hide the critical span. Log candidates and scores and evaluate its added value separately."], ["Why not fine-tune the whole policy corpus?", "It weakens source/update traceability for changing facts. Fine-tuning can improve behavior while governed retrieval supplies applicable evidence."]]}, {"id": "quiz-85137d4d69e3", "topic": "rag", "lessonId": "rag-89fac0d2a9", "tag": "Advanced architecture scenarios", "prompt": "A rewrite drops the word 'not' from a policy question. Which metric catches the central problem?", "options": ["Only vector index disk size.", "Only total number of returned chunks.", "Only token streaming speed.", "Intent and constraint-preservation accuracy."], "correct": 3, "explanation": "A rewrite should make the search clearer while preserving entities, constraints and uncertainty. It must not silently invent a different question. 'Which orders are not refundable after 14 days?' must not become 'refundable orders within 14 days.' Losing negation reverses the requested answer even if retrieval scores improve.", "technical": "Retain the original query, use typed extraction for critical constraints and validate entity/date/negation preservation. Search original and rewritten variants where beneficial, deduplicate and rerank evidence, and ask for clarification when ambiguity is material. Log both versions and evaluate semantic drift on labeled difficult cases. Do not let a rewrite expand authorization scope.", "followups": [["Can RRF detect that the rewrite changed intent?", "No. RRF combines ranks; it does not establish semantic fidelity. Validate query meaning and evidence separately."], ["Should conversation history always be included?", "Use relevant permitted history with explicit state. Stale or untrusted history can introduce the wrong entity or outdated constraint."]]}, {"id": "quiz-293e58e504a9", "topic": "rag", "lessonId": "rag-36815e571e", "tag": "Numerical retrieval drills", "prompt": "With k=60, A ranks [1,10] and B ranks [3,3]. Which has the higher RRF score?", "options": ["RRF requires the raw cosine scores before it can be computed.", "B: about 0.03175 versus A's 0.03068.", "A must win because one list places it first.", "They tie because there are two lists."], "correct": 1, "explanation": "RRF gives a result credit for appearing near the top of several ranked lists. It uses rank positions rather than assuming different retrieval scores share one scale. A strong keyword hit at rank 1 may lose to an item consistently near the top of both keyword and vector lists. This is a rank-combination choice, not proof the winning passage answers the question.", "technical": "For document d, RRF(d)=sum_r 1/(k+rank_r(d)), with optional deliberate weights. A result absent from a list contributes zero for that list. The constant controls how sharply high ranks dominate; its optimal value depends on the retrieval task. Deduplicate by stable identity and preserve permission filters before fusion and delivery.", "followups": [["Why not average raw BM25 and cosine scores?", "Their scales and distributions can differ. Calibrated/normalized weighted score fusion is possible, but a naive arithmetic mean can let one score scale dominate."], ["Does RRF eliminate reranking?", "No. It supplies a candidate ordering. A relevance reranker and evidence evaluation can still improve precision, with added latency and model cost."]]}, {"id": "quiz-8a5f18f9a802", "topic": "rag", "lessonId": "rag-01ce3b56c2", "tag": "Retrieval choices and ranking mathematics", "prompt": "Why choose RAG for frequently updated private policy facts?", "options": ["It ensures a model can never ignore a passage.", "It can supply current authorized evidence with provenance without retraining on each update.", "It guarantees retrieved text is always true.", "It makes all evaluation unnecessary."], "correct": 1, "explanation": "RAG addresses access to external evidence. Source governance, freshness, retrieval quality, permissions and generation faithfulness still require explicit engineering.", "technical": "Prompt-only generation relies on available context and learned knowledge. Fine-tuning mainly changes behavior and task capability, though it can encode facts imperfectly. Long-context prompting can work for a small bounded corpus but increases token cost and still requires relevance, access and freshness checks. RAG adds retrieval errors and indexing operations; it is not automatically the best solution.", "followups": [["When should I avoid RAG?", "When the task requires no external facts, the source fits reliably in a small prompt, or a deterministic API already returns the exact answer. Retrieval adds latency and another failure surface."], ["Can RAG and fine-tuning coexist?", "Yes. Fine-tuning can teach format, terminology or tool use while retrieval supplies current evidence. Evaluate each intervention independently to know what improved quality."]]}]}, "vectors": {"title": "Vectors & ingestion", "description": "Index decisions, versioned pipelines, PDFs, OCR, tables and capacity planning", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-16b79e56354c", "topic": "vectors", "lessonId": "vectors-8c159ada36", "tag": "Vector indexing choices", "prompt": "Which statement about FAISS is accurate?", "options": ["It only stores text and cannot index numeric vectors.", "It is a vector similarity search library; a complete service still needs persistence, metadata and access design.", "It automatically provides user authentication and tenant authorization.", "It replaces every transactional database."], "correct": 1, "explanation": "A nearest-neighbor library solves an indexing/search component. Application storage, metadata filtering, updates and permission enforcement require explicit design.", "technical": "FAISS supplies index structures and search primitives. Your application must handle persistence, IDs, metadata, filtering, access control, concurrency, backups and deployment around it. Qdrant/Pinecone capabilities and guarantees depend on product version and deployment; compare filtering, update behavior, tenancy, availability and cost with your workload. Listing all three on a resume does not mean one project used all three.", "followups": [["When is a library enough?", "When corpus size, update frequency and availability needs are manageable and the team can own the surrounding service. Exact search can be reasonable for smaller corpora."], ["Does a vector database replace the source of truth?", "Usually no. Preserve original documents and version metadata so indexes can be rebuilt and evidence audited."]]}, {"id": "quiz-051044f21969", "topic": "vectors", "lessonId": "vectors-19b4ae33b1", "tag": "Vector indexing choices", "prompt": "For unit-normalized vectors, how are dot product and cosine similarity related?", "options": ["They are equal.", "They always have opposite signs.", "Their values are independent by definition.", "Cosine similarity requires the vectors to have different dimensions."], "correct": 0, "explanation": "Cosine is the dot product divided by the product of norms. With both norms equal to one, that denominator is one.", "technical": "cos(x,y)=(x dot y)/(|x||y|). For unit-normalized vectors, dot product equals cosine and squared L2 distance is 2-2*cos(x,y), so they induce equivalent rankings. Without normalization, this equivalence fails. Match query/document preprocessing to the embedding model and index metric. Handle zero vectors rather than dividing by zero.", "followups": [["Does a cosine value of 0.8 mean 80% relevance?", "No. Similarity is not a calibrated probability. Its distribution depends on the model, corpus and query; validate thresholds empirically."], ["Can I mix embeddings from two model versions?", "Not safely by default. Even equal dimensions do not imply aligned coordinate spaces. Re-embed and reindex or maintain separate versioned indexes."]]}, {"id": "quiz-51a03e3a02f3", "topic": "vectors", "lessonId": "vectors-8d1416ad0b", "tag": "Ingestion and document understanding", "prompt": "Why shouldn't vectors from unrelated embedding models be mixed in one index without validation?", "options": ["Every model uses the same globally shared axes.", "Mixing models automatically improves recall.", "Their coordinate spaces may be incompatible even if vector dimensions match.", "Equal dimensions guarantee identical semantics."], "correct": 2, "explanation": "Dimension is only a shape check. Re-embed compatible corpus/query pairs, build a versioned index, evaluate retrieval and plan a reversible migration.", "technical": "Version the tokenizer/model, normalization, dimensions, chunking and metric as a single retrieval configuration. Re-embed the same authorized corpus snapshot, dual-write new changes, and shadow production queries without exposing duplicate responses. Compare relevance and latency by slice. Keep document IDs stable across versions so judgments and audits remain comparable.", "followups": [["How do you avoid inconsistent freshness during migration?", "Track source versions in both pipelines and establish a synchronization checkpoint before cutover. Validate deletions and ACL updates, not just successful insertions."], ["What triggers rollback?", "Predefined regressions in critical query slices, latency SLOs, permission behavior or ingestion stability. Keep the old index current until the rollback window closes."]]}]}, "evaluation": {"title": "Evaluation", "description": "Formulas, examples, experiments and production diagnosis", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-28c71fe2abb9", "topic": "evaluation", "lessonId": "evaluation-2a9f662ba4", "tag": "Define what success means", "prompt": "Can an answer be faithful to retrieved context but still wrong for the user?", "options": ["No; faithfulness is identical to real-world accuracy.", "Only if the model has fewer than one billion parameters.", "Yes; the context can be obsolete, inapplicable or itself incorrect.", "No; any citation proves full correctness."], "correct": 2, "explanation": "Faithfulness measures support relative to evidence. Correctness also requires that the evidence is authoritative and applicable to the actual question.", "technical": "Decompose an answer into checkable claims and assess support against retrieved context. A fully faithful answer can repeat an obsolete policy; a correct answer can contain uncited knowledge absent from the evidence. RAGAS-style metrics and LLM judges operationalize different definitions, so inspect the version, prompt and required inputs rather than treating the metric name as universal.", "followups": [["How do I evaluate citations?", "Check that each cited source exists, is accessible, corresponds to the stated version and supports its linked claim. Measure unsupported citations and uncited important claims separately."], ["Can an answer be relevant but wrong?", "Yes. A fluent answer can address the question while using the wrong date, entity or units. Relevance is not a substitute for factual validation."]]}, {"id": "quiz-e9e0b1dc0897", "topic": "evaluation", "lessonId": "evaluation-761e8e50dd", "tag": "Define what success means", "prompt": "A query has four relevant documents; top five retrieves two of them. What are precision@5 and recall@5?", "options": ["Both 1.0 because some relevant documents appeared.", "Both 0.2 because only one metric is needed.", "0.4 and 0.5.", "0.5 and 0.4."], "correct": 2, "explanation": "Precision@5 is 2/5. Recall@5 is 2/4 using the labeled relevant set. State how relevance and the evaluation corpus were defined.", "technical": "Precision@k=relevant retrieved/k; Recall@k=relevant retrieved/total relevant. MRR is the mean of 1/rank of the first relevant item, with zero when none is found. DCG@k=sum_i (2^rel_i-1)/log2(i+1); nDCG divides by the ideal DCG for that query. Explicitly define behavior when no relevant items exist and when fewer than k results are returned.", "followups": [["Why can MRR miss a multi-hop failure?", "It only cares about the first relevant hit. A question needing three sources can score well despite missing two. Add evidence-set coverage and final answer evaluation."], ["Why use graded relevance?", "A directly answering passage and a vaguely related document should not always receive the same gain. Define consistent labels and check annotator agreement."]]}, {"id": "quiz-4d2b24151392", "topic": "evaluation", "lessonId": "evaluation-a9e47f103e", "tag": "Experiments and production evidence", "prompt": "What is a responsible use of an LLM judge?", "options": ["Treat every judge score as a verified factual label.", "Evaluate only the examples used to tune the judge prompt.", "Ignore prompt injection in candidate responses.", "Use a defined rubric, validate against human labels and inspect bias/disagreement."], "correct": 3, "explanation": "Model judges are useful evaluators, but not ground truth by default. Track agreement, position/style biases and task-specific failure cases.", "technical": "Supply a rubric, source evidence and explicit scoring categories. Calibrate against blinded human annotations, test order/verbosity bias and measure disagreement. Avoid letting the evaluated model's own persuasive explanation determine the grade. For comparisons randomize answer order and repeat a subset. Store grader model/version and prompts.", "followups": [["What if experts disagree?", "Resolve ambiguous rubric definitions, retain disagreement where the task is genuinely ambiguous and use adjudication for high-impact labels. Report agreement rather than hiding it."], ["What should remain deterministic?", "Schema checks, authorization, numeric tolerances and SQL allowlists should use explicit code where possible. A judge should not decide whether a user has permission."]]}]}, "agents": {"title": "Agents & MCP", "description": "Durable workflows, controlled tools, Rasa integration and failure recovery", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-534d669d70a6", "topic": "agents", "lessonId": "agents-429d136c68", "tag": "Advanced recovery scenarios", "prompt": "An agent is paused at a required human approval. What should monitoring show?", "options": ["Automatic approval after any short model timeout.", "Completed because planning finished.", "An explicit awaiting-approval state with age, approver scope and resume rules.", "A crashed state that must restart with a new operation ID."], "correct": 2, "explanation": "A deliberately paused workflow is different from a failed or looping workflow. Its status should explain what it is waiting for and how it can safely resume. An expense agent has prepared a refund but waits for an authorized approver. Restarting it with a new run ID can create a duplicate intent; the UI should show the existing pending operation and approval controls.", "technical": "Represent running, awaiting approval, retrying, failed, cancelled and completed states explicitly. Store a durable checkpoint, authorized approver identity, expiry and operation intent. On resume, recheck current permissions and data freshness; a checkpoint does not preserve authorization forever. Apply separate deadlines for active computation and business approval windows.", "followups": [["What if the approver's role changed?", "Check current authorization at approval/resume. A previously issued notification is not permanent permission."], ["What should a watchdog restart?", "Only a classified recoverable execution failure under an idempotent policy, not every run with no recent tokens or one awaiting approval."]]}, {"id": "quiz-d8878123f348", "topic": "agents", "lessonId": "agents-d999984d3a", "tag": "Advanced recovery scenarios", "prompt": "A critic sends the same artifact back repeatedly. What is a robust termination policy?", "options": ["Remove all validation to force completion.", "Bounded rounds, explicit acceptance checks and escalation on no progress.", "Continue until all agents sound confident.", "Increase every agent's temperature indefinitely."], "correct": 1, "explanation": "More discussion is not always more progress. Define what a valid result is, how many revisions are allowed and when disagreement should be escalated. A generator and reviewer repeat the same proposed schema change for ten rounds. After the configured two failed correction rounds, return the validation failures and route to a human rather than consume the remaining budget silently.", "technical": "Use typed acceptance checks, bounded rounds, per-step and total cost/deadline budgets, explicit unresolved outcomes and durable evidence. Compare artifact changes rather than counting messages. Prefer a deterministic validator for machine-checkable requirements; model critics can share the generator's biases and cannot prove correctness by agreement.", "followups": [["Does majority voting by three agents guarantee correctness?", "No. Correlated models can agree on the same error. Use independent evidence and task-appropriate validation."], ["What counts as progress?", "A relevant artifact change or satisfied requirement, not just new wording. Record failed constraints and compare outputs against them."]]}, {"id": "quiz-9dab68701239", "topic": "agents", "lessonId": "agents-3b2205502a", "tag": "LangGraph and agent fundamentals", "prompt": "When is a multi-agent design justified?", "options": ["Whenever a task mentions AI.", "Because more agents mathematically guarantee more accuracy.", "When there is no budget for coordination or failure handling.", "When decomposition provides measured value over a simpler workflow under the task's constraints."], "correct": 3, "explanation": "Multiple agents add state, coordination and correlated failure modes. Compare against deterministic or single-agent baselines and measure success, latency, cost and recovery.", "technical": "Define ownership, message contracts, shared state and termination. Compare with a single-agent or deterministic baseline. Multiple agents can share the same biases, duplicate work and create inconsistent evidence, so agent count is not a quality metric.", "followups": [["Does voting guarantee truth?", "No. Correlated models can confidently agree on the same error. Diversity and external evidence matter."], ["How do you measure benefit?", "Task success, distinct error reduction, extra latency/cost and coordination failures at comparable budgets."]]}]}, "backend": {"title": "Backend & SDKs", "description": "FastAPI, Java integration, authentication, Redis and concurrency", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-d44de726c636", "topic": "backend", "lessonId": "backend-5614474e56", "tag": "Defend your Java-to-Python integration", "prompt": "A user is authenticated. What still needs checking before reading an order?", "options": ["Authorization for that specific order and operation.", "Nothing; login grants every database row.", "Only whether the order ID has valid JSON syntax.", "Whether the model is confident the order exists."], "correct": 0, "explanation": "Identity and resource permission are separate. The backend must derive the trusted principal and enforce ownership, tenant and current policy on the requested operation.", "technical": "Validate token signature using trusted keys and allowed algorithms, plus issuer, audience, expiry and relevant claims. JWT contents are generally encoded, not encrypted. RBAC maps roles to permissions; ABAC evaluates attributes such as tenant, ownership and purpose. Enforce authorization for every object/action and plan revocation, refresh and key rotation.", "followups": [["Why not store passwords in JWTs?", "Tokens should not contain secrets or unnecessary sensitive data. Passwords belong in a secure authentication flow and appropriately hashed storage where applicable, never in readable session claims."], ["Is CORS an authorization mechanism?", "No. It controls browser cross-origin access behavior. Non-browser clients can still call the API; authentication and authorization must be enforced independently."]]}, {"id": "quiz-efafedff2fe3", "topic": "backend", "lessonId": "backend-8f479f38ce", "tag": "Scaling and failure semantics", "prompt": "Why is cache key='question text' unsafe for a private account assistant?", "options": ["It omits identity/resource scope and can return another user's answer.", "It is always safe if the cache is encrypted.", "Hashing the same insufficient key always fixes authorization.", "Private answers can always be shared after one successful query."], "correct": 0, "explanation": "Include the scope and relevant version/freshness dimensions, and ensure permission is valid at delivery. Encryption does not repair a logically incorrect shared key.", "technical": "A cache key may need normalized query, tenant, permission scope/version, corpus version, model/prompt version and relevant input parameters. Use TTLs plus event-driven invalidation where necessary. Prevent stampedes with bounded single-flight or refresh coordination. Cache failures and partial results only under a deliberate policy. A semantic cache needs stricter equivalence checks than string matching.", "followups": [["Why is a distributed lock not automatically enough?", "Locks can expire while work continues, and processes can crash. Use fencing or version checks where stale writers could corrupt state; often idempotent versioned writes are simpler."], ["What is negative caching?", "Temporarily caching a miss or known unavailable result reduces repeated work. Its TTL should be short enough to avoid hiding newly available data or corrected permissions."]]}, {"id": "quiz-5674db34956d", "topic": "backend", "lessonId": "backend-57ea774360", "tag": "Scaling and failure semantics", "prompt": "What does an outbox pattern help coordinate?", "options": ["Removal of the need for consumer idempotency.", "Unlimited database write throughput.", "A durable application state change and an event intent in the same local transaction.", "A guarantee of exactly-once effects in every remote service."], "correct": 2, "explanation": "A transactional outbox avoids the gap between a local commit and recording an event to publish. The publisher and consumer still need retry, deduplication and reconciliation policies.", "technical": "Brokers and databases have different transaction boundaries. An outbox writes a business change and an event record in one local transaction; a dispatcher publishes the event later. Consumers deduplicate using stable event/operation IDs. 'Exactly once' must be scoped to a specific system boundary; it is not a universal end-to-end guarantee across arbitrary HTTP services.", "followups": [["What if the consumer crashes after performing the effect?", "On replay it must identify the completed operation or reconcile with the downstream system. Acknowledging only after work helps delivery but does not by itself prevent duplicates."], ["How do you preserve ordering?", "Partition by an appropriate entity key and compare versions. Do not assume global ordering; reject or ignore stale updates that arrive after newer ones."]]}]}, "gpu": {"title": "GPU & vLLM", "description": "Memory arithmetic, batching, kernels, quantization and serving diagnosis", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-9e5bb3d9199f", "topic": "gpu", "lessonId": "gpu-06fb97712c", "tag": "Understand the serving workload", "prompt": "Ignoring overhead, roughly how much memory do 7 billion FP16 weights occupy?", "options": ["Exactly 7 GiB regardless of dtype.", "Zero if the model uses a KV cache.", "14 billion bytes, about 13.0 GiB.", "7 megabytes."], "correct": 2, "explanation": "Each FP16 weight uses two bytes. Serving also needs KV cache, runtime buffers, activations and allocator headroom; a weight-only estimate is not a deployment guarantee.", "technical": "A 7-billion-parameter model at two bytes/parameter needs about 14 GB decimal for weights alone. Four-bit storage has a theoretical payload of 3.5 GB, but scales, zero points, unquantized layers, alignment and runtime workspaces add overhead. Serving also needs KV cache, activations, kernels and allocator headroom. Training adds gradients and optimizer state.", "followups": [["Is BF16 smaller than FP16?", "Both commonly use 16 bits per value. They differ in exponent and mantissa allocation, affecting range and precision, not basic storage size."], ["Can I infer memory from the model name?", "Not reliably. Check actual parameter count, architecture, quantization format, expert structure and loaded tensors. Some layers may remain higher precision."]]}, {"id": "quiz-df3be5156d60", "topic": "gpu", "lessonId": "gpu-d46bbdc7fd", "tag": "Understand the serving workload", "prompt": "What distinguishes continuous batching in LLM serving?", "options": ["All users must generate the same number of tokens.", "KV cache becomes unnecessary.", "Every request is processed entirely alone.", "Finished requests can leave and new requests can join active generation scheduling."], "correct": 3, "explanation": "Token-level scheduling can improve utilization for varying request lengths. Assess the actual scheduler, fairness, tail latency and memory budget.", "technical": "Fixed batches waste capacity when short sequences finish before long ones. Continuous scheduling admits new work into freed capacity between decoding iterations, subject to token and memory budgets. Fairness, long prefills and variable output lengths still need management. Larger batches can improve throughput while worsening queueing or per-token latency.", "followups": [["Why not set maximum batch size as high as possible?", "Memory, latency and scheduling overhead impose limits. Optimize throughput subject to TTFT/TPOT and error constraints, not the batch-size number itself."], ["What is token-based admission?", "Capacity is budgeted using prompt and expected/generated token work rather than treating every request as equal. It better captures the difference between tiny and long-context requests."]]}, {"id": "quiz-121ffd177293", "topic": "gpu", "lessonId": "gpu-f8a2b5ab63", "tag": "Understand the serving workload", "prompt": "What does PagedAttention primarily improve?", "options": ["KV-cache memory management using block-based allocation and sharing mechanisms.", "The truthfulness of every generated claim.", "Training labels and source-document authority.", "IAM authorization for cloud resources."], "correct": 0, "explanation": "PagedAttention is a serving/memory technique, not a factuality or access-control mechanism. Its operational value must be measured with the real request mix.", "technical": "Logical sequence blocks map to physical cache blocks rather than requiring one large contiguous allocation per sequence. This reduces waste from over-reservation and fragmentation and supports efficient scheduling. It does not compress model weights or remove the mathematical need for token state. Its benefit depends on request lengths, sharing, scheduling and hardware.", "followups": [["Is PagedAttention the same as an operating-system swap file?", "No. The analogy is block-based address management; it is not a claim that GPU cache is automatically swapped to disk."], ["Does it guarantee faster single-request latency?", "No. Its key advantages are memory management and serving efficiency. Measure latency and throughput under the intended concurrency rather than assuming every request gets faster."]]}]}, "training": {"title": "LoRA, QLoRA & ML", "description": "Adaptation choices, training math, small-data risks and model evaluation", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-48660ca4bc13", "topic": "training", "lessonId": "training-6c737983f7", "tag": "Adaptation choices", "prompt": "For a 1024-by-1024 weight matrix and LoRA rank 8, how many adapter weights are added, excluding biases?", "options": ["8*(1024+1024)=16,384.", "1024*1024=1,048,576 for each adapter factor.", "Only 8 scalar values.", "Zero because the base weights are frozen."], "correct": 0, "explanation": "A rank-r update uses factors of shapes [1024,r] and [r,1024]. Freezing the base matrix does not remove the trainable adapter parameters.", "technical": "For W of shape d_out by d_in, represent the update as (alpha/r)BA, with A of shape r by d_in and B of shape d_out by r. Standard LoRA trains A and B while W stays frozen. Trainable parameters for this matrix are r*(d_in+d_out), instead of d_in*d_out. Implementations may use alternative scaling; report the actual configuration.", "followups": [["What does rank mean?", "It bounds the rank/capacity of the learned update. Higher rank increases trainable parameters and possible expressiveness, but can overfit and does not guarantee a better model."], ["Can an adapter be merged?", "Often the update can be added into compatible base weights for inference. Quantized formats and runtime support can complicate merging; validate numerical behavior and preserve the original base/adapter versions."]]}, {"id": "quiz-b00871fa71f7", "topic": "training", "lessonId": "training-316b8d02e5", "tag": "Adaptation choices", "prompt": "What is the core QLoRA setup?", "options": ["Replace retrieval with a SQL database.", "Guarantee zero GPU memory for optimizer states.", "Train low-rank adapters while using a quantized frozen base model under the method's design.", "Fine-tune every original weight in FP32 with no adapters."], "correct": 2, "explanation": "QLoRA combines parameter-efficient adaptation with quantized base-weight storage and other memory-oriented techniques. Total training memory includes more than base weights.", "technical": "The QLoRA paper combines a four-bit base representation using NF4, double quantization of quantization constants and paged optimizers. Computation is not simply all four-bit arithmetic: weights are used through supported dequantization/compute paths, while adapters and other states use suitable higher precision. Gradients update adapters rather than the frozen quantized base.", "followups": [["Is QLoRA an inference engine?", "No. It is an adaptation method. Serving the resulting adapter requires compatible base weights and runtime support, and its speed must be measured separately."], ["Does four-bit training guarantee no quality loss?", "No. Quantization and adaptation can affect tasks differently. Evaluate the exact checkpoint on held-out cases, especially numeric, rare-domain and safety-sensitive outputs."]]}, {"id": "quiz-c483cb3d81d1", "topic": "training", "lessonId": "training-4a36950fc1", "tag": "BERT and training fundamentals", "prompt": "Which evidence best detects adapter overfitting?", "options": ["The number of decorative charts in the report.", "Reusing the final test set for every hyperparameter choice.", "Held-out task performance and slice evaluation alongside the training/validation loss trend.", "Training loss alone dropping to zero."], "correct": 2, "explanation": "A lower training loss can reflect memorization. Keep a clean evaluation set, representative slices and a comparison to the unadapted baseline.", "technical": "Deduplicate before splitting; group related document versions, templates and clients appropriately. Use early stopping, suitable regularization and data quality checks. Compare with the base model and a simple non-neural baseline when appropriate. Evaluate rare classes and out-of-domain inputs, not just the common training distribution.", "followups": [["Is perplexity comparable between arbitrary tokenizers?", "Not directly. Tokenization changes the units and likelihood decomposition. Compare under consistent tokenization/objectives or use task-level measures."], ["What if labels are scarce?", "Use a smaller adjudicated evaluation set, weak supervision only with measured noise, and learning curves. Synthetic data requires validation and separation from test material."]]}]}, "sql": {"title": "SQL & databases", "description": "Queries, joins, transactions, schemas and database reasoning", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-32f436b6ac47", "topic": "sql", "lessonId": "sql-4104196cfe", "tag": "SQL and DBA follow-ups", "prompt": "With no GROUP BY, what is the difference between COUNT(*) and COUNT(column)?", "options": ["Both always ignore rows containing any null anywhere.", "COUNT(column) counts only distinct values automatically.", "COUNT(*) only counts indexed rows.", "COUNT(*) counts rows; COUNT(column) counts non-null values in that column."], "correct": 3, "explanation": "A null in a chosen column is excluded from COUNT(column), while COUNT(*) counts the row. COUNT(DISTINCT column) is a separate operation.", "technical": "SQL uses three-valued logic for nulls. A WHERE predicate on a nullable right-side column after a LEFT JOIN can remove unmatched rows and effectively change the intended outer-join behavior. COUNT(DISTINCT column) removes duplicate non-null values. Define the business grain before choosing a counting expression.", "followups": [["Why does NULL = NULL not behave like ordinary equality?", "NULL represents unknown/missing, so the comparison is unknown rather than true. Use IS NULL for null tests and understand dialect-specific null-safe comparisons."], ["Can HAVING replace every WHERE condition?", "It may be inefficient or change meaning because filtering occurs after grouping. Apply row filters before aggregation when that matches the task."]]}, {"id": "quiz-1b90f6523754", "topic": "sql", "lessonId": "sql-bbf5d55858", "tag": "Database foundations for Text-to-SQL", "prompt": "What is the correct purpose of parameterized SQL?", "options": ["Allow a model to choose arbitrary table names without checks.", "Grant database owner permissions to every caller.", "Keep data values separate from query syntax, while separately validating dynamic identifiers.", "Concatenate user text after escaping only spaces."], "correct": 2, "explanation": "Bound values reduce injection through those values. Dynamic table/column names require an explicit allowlist or safe query-construction boundary; parameters do not implement authorization.", "technical": "Bind values through the database driver rather than string concatenation. Identifiers such as table names often cannot be parameterized the same way, so validate them against an allowlist/schema. Generated SQL still needs AST, object and resource controls.", "followups": [["Does parameterization make all generated SQL safe?", "No. The query can still access forbidden data or be too expensive. Permissions and policy validation remain necessary."], ["Why not just escape quotes?", "Manual escaping is dialect- and context-sensitive and easy to get wrong. Use supported binding APIs."]]}, {"id": "quiz-df24d0caacd2", "topic": "sql", "lessonId": "sql-ea1625743a", "tag": "SQL and DBA follow-ups", "prompt": "How does a window sum differ from GROUP BY aggregation?", "options": ["It cannot use ordering.", "It automatically removes duplicates.", "It can compute a partition total while retaining the original rows.", "It always collapses all rows into one."], "correct": 2, "explanation": "Window functions operate over a specified partition/frame and keep row-level output. GROUP BY produces one result row per group, with different semantics.", "technical": "A window specifies partitioning, ordering and optionally a frame. ROW_NUMBER gives a unique sequence under a defined order; RANK and DENSE_RANK handle ties differently. Running totals depend on frame semantics; an implicit default can differ from the intended row-by-row calculation. Add deterministic tie-breakers when stable results matter.", "followups": [["Why not MAX(order_date) alone?", "It gives a date per group, not automatically the entire corresponding row, and ties may produce several rows when joined back."], ["What is a CTE?", "A named query expression that improves structure and can support recursion in supported dialects. Do not assume it is always materialized or always faster; inspect the optimizer plan."]]}]}, "deployment": {"title": "Cloud & full stack", "description": "Deployment, maintenance, operational debugging and full-stack interview coverage", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-ff5a861f4fd7", "topic": "deployment", "lessonId": "deployment-f97a1014cf", "tag": "Deployment and operations", "prompt": "An application on Linux is down. What is a useful initial diagnostic sequence?", "options": ["Delete all logs before investigating.", "Reboot every host repeatedly without evidence.", "Change the model temperature before checking the process.", "Check process/service status, logs, listening port, dependencies and resource pressure."], "correct": 3, "explanation": "Start with observable serving boundaries and recent changes. Correlate the service status and logs with port/network reachability and critical dependency health.", "technical": "Inspect service status and journal logs, process/CPU/memory usage, disk space/inodes, network listeners, DNS and connectivity. Check configuration changes, permissions, certificate expiry and dependency health. Use targeted commands and preserve incident evidence; repeated restarts can hide the cause or worsen load.", "followups": [["Liveness versus readiness?", "Liveness asks whether the process should be restarted. Readiness asks whether it should receive traffic. A dependency outage should not automatically trigger endless restarts if the process can recover."], ["What if disk is full?", "Identify the responsible filesystem and files, check log rotation and retention, and follow an approved cleanup/recovery procedure. Do not blindly delete database files or active logs."]]}, {"id": "quiz-97bbf0e4ea08", "topic": "deployment", "lessonId": "deployment-66030f9a8f", "tag": "Deployment and operations", "prompt": "What should a GenAI deployment gate evaluate beyond syntax?", "options": ["Only whether the frontend has an AI logo.", "Only the number of generated tokens.", "The final test set after tuning on every one of its labels.", "Representative task quality, permission boundaries and relevant failure/rollback behavior."], "correct": 3, "explanation": "A working build can still regress retrieval, authorization, formatting or latency. Choose checks tied to the change and keep a rollback plan.", "technical": "Run lint/type checks where useful, unit/contract tests, security/dependency checks, image builds and a representative evaluation suite. Version prompts, datasets, retrieval configuration and model adapters as deployable artifacts. Use regression gates for critical tasks and access-control behavior. Slow comprehensive evaluations can run separately from fast pull-request checks, but promotion criteria must be explicit.", "followups": [["How do you handle nondeterministic evaluations?", "Use stable cases, repeated measurements where justified, tolerance bands and human adjudication for consequential changes. Avoid a flaky gate based on one sampled response."], ["Can I roll back only the prompt?", "Yes if prompt/model/tool/schema versions remain compatible. Track the whole configuration bundle so a rollback restores a coherent system."]]}, {"id": "quiz-1839aa6eec70", "topic": "deployment", "lessonId": "deployment-96d9ca3c7e", "tag": "Deployment and operations", "prompt": "What makes application rollback reliable?", "options": ["Deleting all database backups before release.", "Assuming schema changes reverse themselves.", "A known compatible artifact/configuration and a plan for state/schema compatibility.", "Only checking out any older source file."], "correct": 2, "explanation": "Rollback must account for code, configuration and persisted state. Some migrations need a forward repair or compatibility window rather than blindly running old code.", "technical": "Run under a dedicated low-privilege service identity, use a service manager, externalize configuration and secrets, and configure graceful shutdown. Apply migrations using a backward-compatible expand/contract strategy when possible. A code rollback cannot undo an incompatible database migration automatically. Separate deployment success from application readiness.", "followups": [["What if requests are in flight?", "Drain connections and allow a bounded graceful period. Durable jobs must be resumable; do not assume killing the process safely cancels external side effects."], ["Blue-green versus canary?", "Blue-green switches between environments; canary gradually sends a subset of traffic to the new version. Both need compatibility, observability and a rollback plan."]]}]}, "domains": {"title": "Domain scenarios", "description": "Nine architecture deep-dives with alternatives, follow-ups and production decisions", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-89d221dfc51b", "topic": "domains", "lessonId": "domains-88fa95b0f1", "tag": "Healthcare design drills", "prompt": "Two patients share a name. What should scope a clinical summary's retrieval?", "options": ["A verified patient ID from trusted application context and current authorization.", "Only semantic name similarity.", "The first chart the model remembers.", "All matching records merged to maximize recall."], "correct": 0, "explanation": "Patient identity must come from a trusted application selection and authorization flow. The model must not infer identity from a name in free text. Two patients named Alex Lee have different IDs. A summary request opened from patient A's chart must never search both charts by name similarity. A record with a conflicting patient ID should be rejected or quarantined before generation.", "technical": "Bind each request and retrieval query to a verified patient identifier and current user's permitted scope. Use source-level provenance and encounter timestamps, detect conflicting identifiers and stop ambiguous requests. Keep a human review path for clinical use. These are architecture exercises, not claims that this design alone satisfies legal or clinical requirements.", "followups": [["Would a prompt saying do not mix patients be enough?", "No. Enforce patient scoping before retrieval and verify provenance independently of the model's text."], ["Should the assistant make autonomous treatment changes?", "Not as a consequence of this summarization design. Clinical authority, review and validated scope must be defined separately."]]}, {"id": "quiz-14737f6d7ff6", "topic": "domains", "lessonId": "domains-5cb8c92a82", "tag": "Healthcare design drills", "prompt": "A newer adult guideline conflicts with an older pediatric guideline for a child. What matters first?", "options": ["Raise temperature to choose randomly.", "Applicable population, authority and effective scope before simple recency.", "Always choose the document with the newest upload timestamp.", "Merge both into one instruction without citing the conflict."], "correct": 1, "explanation": "Recency is one clue, but applicability, authority, population and effective dates determine which evidence belongs to the case. Do not silently merge incompatible recommendations. A newer adult policy cannot automatically replace an older pediatric guideline for a child. The system must match population and setting before comparing dates.", "technical": "Store provenance, issuer, jurisdiction, effective/version dates and population scope. Retrieve applicable sources, surface conflicts, distinguish historical from current guidance and route unresolved material conflicts to an appropriate professional. RAG supports access to governed evidence; fine-tuning does not automatically resolve a changing clinical source hierarchy.", "followups": [["Why not fine-tune all guidelines into the model?", "Updates and conflicting scopes need traceable evidence and source governance. Fine-tuning may improve task behavior but does not supply reliable current citations by itself."], ["Can the model rank clinical authority alone?", "It can assist analysis, but authority and applicability rules should come from governed domain policy and professional oversight."]]}, {"id": "quiz-917fb716275e", "topic": "domains", "lessonId": "domains-721dcc11b5", "tag": "Cybersecurity design drills", "prompt": "A threat report instructs the assistant to disable logs. What is the trust boundary?", "options": ["Allow all shell commands if a second model agrees.", "Treat the report as data; independently authorize any tool action.", "Treat retrieved text as a system instruction.", "Disable logs because the report sounds technical."], "correct": 1, "explanation": "Threat reports are untrusted evidence, not operational commands. A report cannot grant itself permission to change security settings. A malicious report says run a command that disables audit collection before analyzing an indicator. The assistant can quote that text as suspicious evidence while the tool layer rejects any unauthorized configuration change.", "technical": "Separate extraction of indicators and claims from action authorization. Use trusted tool definitions, per-action permission checks, destination/resource allowlists and explicit review for high-impact changes. Preserve provenance and test indirect prompt-injection cases. A detector model can supplement controls but cannot replace server-side restrictions.", "followups": [["Is read-only access harmless?", "No. Unauthorized reads can disclose secrets through responses, caches or logs. Scope retrieval and output as well as writes."], ["Can a second agent approve every command?", "It may help review but can share the same failure modes. Enforce permissions and high-impact approvals outside model text."]]}, {"id": "quiz-0fe26a2c6b02", "topic": "domains", "lessonId": "domains-b20a8469bf", "tag": "Cybersecurity design drills", "prompt": "With capacity to review 500 alerts per day, which metric is directly useful?", "options": ["Precision at that review budget, alongside critical-event recall.", "Overall accuracy alone on a mostly benign dataset.", "Number of generated paragraphs per alert.", "Alert volume maximized without regard to backlog."], "correct": 0, "explanation": "Optimize for useful investigations under a real review budget. Detecting everything is not operational success if important cases disappear in a backlog. One noisy endpoint produces 5,000 near-identical alerts. Group them into a single incident with event counts and time range, while preserving evidence and escalating a distinct high-impact event on a critical asset.", "technical": "Deduplicate correlated events, enrich with asset criticality and trustworthy threat context, group incidents and rank by severity/likelihood/impact. Calibrate thresholds on representative labeled data and track selection bias from reviewed cases. Keep deterministic escalation rules for defined critical conditions. LLM summaries can aid triage without becoming the authoritative detector.", "followups": [["Why is accuracy a weak target?", "True negatives dominate many detection tasks. Precision at a fixed analyst budget and critical recall better reflect the workflow's constraints."], ["How do you learn from unreviewed alerts?", "Do not treat unreviewed as benign. Use delayed confirmed outcomes and a designed sampling strategy to reduce feedback bias."]]}, {"id": "quiz-2fd78cb327b6", "topic": "domains", "lessonId": "domains-146fe399bd", "tag": "Finance design drills", "prompt": "Before adding financial figures from two sources, what must you validate?", "options": ["Whether temperature is below 0.5.", "Compatible currency, scale, reporting period, entity and measure.", "Only whether both values are valid floating-point numbers.", "Only that both sources contain a currency symbol."], "correct": 1, "explanation": "Correct arithmetic on incompatible numbers still produces a wrong business answer. Units, entity, period and accounting meaning must travel with every value. Adding USD 10 million for Q1 to EUR 8 million for an entire year is not a meaningful comparable total. First align scope and period, then use a documented exchange rate if conversion is part of the task.", "technical": "Retrieve structured values with currency, scale, effective period, entity, source and revision. Validate compatible operands before deterministic calculation, apply an explicit exchange-rate policy when permitted and produce traceable citations. Keep the LLM focused on interpretation and explanation; use typed calculations and business rules for authoritative totals.", "followups": [["Why not let the LLM do all calculations?", "Deterministic tools provide reproducible arithmetic and explicit types. The model can still misunderstand scope, so validate inputs before calling the tool."], ["What if two filings restate the same period?", "Track revision and authority, preserve provenance and use the version required by the question. Surface a material restatement rather than counting both."]]}, {"id": "quiz-e028df40bc6b", "topic": "domains", "lessonId": "domains-84c301ded1", "tag": "Finance design drills", "prompt": "Which component should authorize a transaction-blocking effect?", "options": ["A policy-controlled decision service using validated inputs and permissions.", "The assistant's prose confidence alone.", "Any retrieved document mentioning fraud.", "The highest-temperature generated explanation."], "correct": 0, "explanation": "An explanation assistant, a risk model and a transaction decision service have different responsibilities. Natural-language confidence should not become a payment-blocking rule. A high amount is unusual for one customer but normal for another. An assistant can summarize that context, while a policy-controlled decision layer combines calibrated risk, customer history and action thresholds.", "technical": "Use a validated risk model or rules for scoring and an authorized decision service for effects. Retrieve case evidence with timestamps, distinguish observed facts from hypotheses and expose reason codes faithfully. Apply review and appeal/escalation paths appropriate to the business. RAG provides evidence access; it is not automatically a calibrated fraud classifier.", "followups": [["Can a persuasive explanation make a poor score reliable?", "No. It can conceal uncertainty. Evaluate scoring and explanatory faithfulness independently, including cases where evidence is weak."], ["What should the assistant do with missing evidence?", "State the missing field or uncertainty and use the defined review path. Do not invent a causal story to fill a fluent paragraph."]]}, {"id": "quiz-d4004c6c7dba", "topic": "domains", "lessonId": "domains-e357cca373", "tag": "Customer and operations scenarios", "prompt": "A refund request times out after reaching the payment service. What should happen next?", "options": ["Reconcile the original idempotent operation before retrying.", "Issue a new refund immediately with a new ID.", "Assume no money moved because the UI timed out.", "Give the model direct owner-level SQL credentials."], "correct": 0, "explanation": "A refund is a specific business operation with eligibility and authorization rules. A narrow refund API can enforce them better than unrestricted database access. If the customer repeats a request after a timeout, the same logical refund operation should return its recorded status. A new unrestricted SQL write or new payment ID could create a second refund.", "technical": "Bind the request to authenticated ownership, check order state and refund policy, calculate the permitted amount deterministically and require the appropriate confirmation/approval. Use an idempotency key and reconcile uncertain payment outcomes. Retrieve policy explanations separately from the effectful refund operation.", "followups": [["Can retrieved policy text authorize a refund?", "No. The trusted backend enforces the approved policy and current order/user state. Retrieval supplies explanatory evidence, not authority."], ["Does a timeout mean the refund failed?", "No. Reconcile the provider's original operation before deciding whether to retry or escalate."]]}, {"id": "quiz-31a983161088", "topic": "domains", "lessonId": "domains-2cafda9ec0", "tag": "Customer and operations scenarios", "prompt": "A termination answer omits a cross-referenced exception. What should retrieval preserve?", "options": ["A fixed answer memorized during fine-tuning.", "Clause links, definitions, amendments and applicable surrounding evidence.", "Only the highest-scoring isolated sentence.", "Only vector distance without document identity."], "correct": 1, "explanation": "A clause can depend on definitions, cross-references and amendments. Retrieve the necessary surrounding evidence and expose uncertainty instead of presenting a legal conclusion as certain. A termination clause says 30 days' notice except for a defined breach event elsewhere. A summary that quotes only the 30-day sentence is supported locally but incomplete for the actual question.", "technical": "Preserve document hierarchy, clause IDs, definitions, amendment precedence and parties/effective dates. Retrieve parent/linked clauses when justified, trace every substantive claim to spans and evaluate exceptions/negation explicitly. Use qualified review for consequential interpretation. Adding all documents to context can bury the exception and exceed the token budget.", "followups": [["Does a citation prove the complete answer is correct?", "No. A citation can support one sentence while missing a material exception. Evaluate completeness and applicability as well as support."], ["Why not fine-tune instead of RAG?", "Contract-specific and amended facts need traceable current evidence. Fine-tuning can improve extraction behavior but does not replace access-controlled source lookup."]]}]}, "resume": {"title": "Resume prep", "description": "Project deep-dives, ownership, evidence checks and defensible spoken answers", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-a155ce69780f", "topic": "resume", "lessonId": "resume-ce6658f6e0", "tag": "Broader experience and final rehearsal", "prompt": "How should you defend a claimed project improvement in an interview?", "options": ["Repeat the percentage without its definition.", "Substitute a hypothetical benchmark for the original result.", "Claim the whole team's work as solely your own.", "Explain the baseline, dataset, denominator, measurement setup and your contribution."], "correct": 3, "explanation": "A defensible result has a defined metric and comparison under stated conditions. If evidence is unavailable, describe the limitation and what you can verify.", "technical": "Priority items are the 87.5% SQL claim, generic SQL dataset provenance, actual execution deployment, Flask/FastAPI component history, LangGraph node behavior, exact model/provider runs, BERT training configuration and GPU optimization results. For KEDB/log productivity figures collect baseline, sample size and timing definitions. Verify official job title and certification names/issuers against your records; a certification is not proof of every associated implementation skill.", "followups": [["Should I remove all metrics until perfect evidence exists?", "Use figures you can substantiate and qualify estimates or user-reported impact. Correct known inaccuracies before use; this guide itself does not edit the resumes."], ["What is the strongest way to answer a gap?", "State the limitation, explain how you would measure or fix it, and connect that plan to the observed failure. This demonstrates judgment without inventing completed work."]]}, {"id": "quiz-762b53ec2585", "topic": "resume", "lessonId": "resume-bf3d39837b", "tag": "Rasa, SDKs and enterprise integration", "prompt": "What distinguishes a Python SDK from a FastAPI service?", "options": ["An SDK is a callable client/library boundary; FastAPI exposes a network API with request handling.", "They are necessarily the same deployed process.", "An SDK automatically provides end-user authorization.", "FastAPI is a vector similarity index."], "correct": 0, "explanation": "Explain the actual boundary, typed contracts, credential handling and who enforces resource permissions. A client wrapper does not replace server-side authorization.", "technical": "You requested this experience be added: Java/Spring Boot services integrated through reusable Python SDKs, exposed backend capabilities through FastAPI, and used MCP for chatbot development with authentication and authorization. Clarify whether you wrapped existing REST APIs or rewrote selected service logic. Identify token acquisition/validation, scopes, object-level checks, retries, timeouts and error translation from actual implementation.", "followups": [["Where is authorization enforced?", "At the backend/tool boundary for the requested resource, with verified principal/tenant context. A frontend check or prompt instruction is insufficient."], ["What if the model changes the account ID?", "The server must reject access to an unauthorized object even when the tool name and schema are valid. Explain your implemented protection or label it as a necessary improvement."]]}]}, "mock": {"title": "Mock interviews", "description": "Five practice rounds, answer keys and a four-week rehearsal plan", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-9cd6f5c01798", "topic": "mock", "lessonId": "mock-5b418e304e", "tag": "Practice one question at a time", "prompt": "A policy update causes a previously correct RAG answer to become stale. What do you trace?", "options": ["Source revision, ingestion/index update, filters, caches and the rendered evidence.", "Only the total number of GPU cores.", "Only the response's writing style.", "Temperature as the sole freshness control."], "correct": 0, "explanation": "Follow the fact through its lifecycle. Identify whether stale content persists in storage, retrieval, caches or prompt assembly before choosing a repair.", "technical": "Check publication versus effective date, failed ingestion, mixed chunks, stale replicas, permissions and cache keys. Replay an affected query with current oracle evidence and with cache disabled in a controlled test. If oracle evidence fixes the answer, focus on retrieval/freshness; otherwise inspect generation and conflict handling. Repair the first failing boundary and serve a clear degraded response where needed.", "followups": [["What if only some users fail?", "Compare tenant/role filters, cache partitions and regional replicas. It may be permission-specific or a selective-filter recall issue rather than a global model regression."], ["What catches this earlier?", "Freshness lag, correct-version answer rate and canary questions for recently changed policies, alongside cache/version telemetry."]]}, {"id": "quiz-038f4f683292", "topic": "mock", "lessonId": "mock-89f330da2a", "tag": "Practice one question at a time", "prompt": "An agent creates two tickets after a timeout. What is the central repair?", "options": ["Deleting checkpoints and hiding the duplicates.", "Durable operation IDs, idempotent creation and reconciliation of unknown outcomes.", "A new ticket ID on every retry.", "More agents voting that the first request failed."], "correct": 1, "explanation": "The remote action may succeed even when the client misses the response. Tie retries to the same logical operation and reconcile before repeating effects.", "technical": "The same business request must reuse its ID across retries. Atomically bind the ID to the effect where possible, reject changed payloads and handle in-progress operations. If the downstream cannot support this, add reconciliation and acknowledge the remaining race; a Redis cache written after creation cannot guarantee duplicate prevention by itself.", "followups": [["Is at-least-once delivery the bug?", "It is an expected delivery model. The bug is treating duplicate delivery as a new non-idempotent action without a recovery design."], ["Does a graph checkpoint solve it?", "It preserves workflow state, but a crash can occur between the effect and checkpoint. External action semantics need separate design."]]}]}, "tooling": {"title": "Frameworks & observability", "description": "What each tool does, how components connect and how to defend your choices", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-b28bd600844a", "topic": "tooling", "lessonId": "tooling-19afc53cde", "tag": "Framework and observability questions", "prompt": "Which description best fits LlamaIndex?", "options": ["A guarantee of perfect RAG recall.", "A framework/toolkit for data-to-LLM applications, with ingestion, retrieval and related components.", "A mandatory replacement for all databases and backend security.", "A GPU hardware specification."], "correct": 1, "explanation": "Choose components for the actual data and workflow needs. A framework organizes implementation but does not validate source quality or authorize every resource automatically.", "technical": "Its abstractions include documents/nodes, ingestion, indexes, retrievers and query engines. The framework coordinates components; it is not itself a model or a universal replacement for a vector database. Inspect what an integration actually stores and retrieves.", "followups": [["Why not use direct Python calls?", "Direct code can be clearer for small pipelines. A framework helps when connectors and reusable retrieval abstractions reduce work without hiding needed controls."], ["Does it guarantee accurate RAG?", "No. Parsing, evidence quality, permissions, prompts and evaluation remain your responsibility."]]}, {"id": "quiz-b94f1ebe4934", "topic": "tooling", "lessonId": "tooling-a373270ad0", "tag": "Framework and observability questions", "prompt": "What is a useful role for LangSmith in an LLM application?", "options": ["Replacing all access controls with a dashboard.", "Proving truth solely from a successful trace.", "Automatically eliminating model hallucinations.", "Tracing, datasets and evaluation experiments for observing and comparing runs."], "correct": 3, "explanation": "Traceability helps locate and reproduce failures. Pair it with curated evaluation cases, permissions-aware logging and task-specific metrics.", "technical": "Trace retrieval, model and tool steps with relevant versions and sanitized metadata. It supports multiple frameworks; using LangGraph is not a prerequisite. Enabled tracing still needs access, retention and data-redaction decisions.", "followups": [["Is LangSmith the same as LangGraph?", "No. LangGraph orchestrates execution; LangSmith provides observability/evaluation capabilities around applications."], ["Does an installed dependency mean tracing worked?", "No. Verify configuration and actual trace delivery. The resume should distinguish available instrumentation from observed production coverage."]]}, {"id": "quiz-ccefa8540d59", "topic": "tooling", "lessonId": "tooling-b253f48ce9", "tag": "Framework and observability questions", "prompt": "Which signal is best suited to a latency histogram?", "options": ["An arbitrary increasing request count used as if it were latency.", "A raw session token attached to every metric label.", "Only a screenshot of a dashboard.", "A distribution of request durations from which suitable quantiles/buckets can be assessed."], "correct": 3, "explanation": "Histograms capture distributions, while counters and gauges have different semantics. Avoid high-cardinality/private labels and define the exact timed boundary.", "technical": "Counters accumulate events, gauges represent values that can rise/fall, histograms bucket observations, and summaries provide client-side distribution statistics with specific aggregation limits. Choose labels with bounded cardinality. Exact query/metric behavior depends on configuration.", "followups": [["Why not use a counter for current queue size?", "Queue size decreases as well as increases; a gauge represents it directly."], ["Why avoid user ID labels?", "Each unique label combination creates a series, causing cost and performance problems and potentially exposing identifiers."]]}]}, "systems": {"title": "Production scenarios", "description": "Detailed systems questions modeled on your examples, with step-by-step answers and follow-up chains", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-9a9016c5e312", "topic": "systems", "lessonId": "systems-26c2845ce1", "tag": "Application development scenarios", "prompt": "Which release design reduces stale HTML referencing missing JavaScript?", "options": ["Hashed assets, revalidated entry HTML and compatible atomic deployment.", "Delete old assets immediately and cache index forever.", "Put database credentials in the browser to fetch new code.", "Tell every user to reinstall their operating system."], "correct": 0, "explanation": "The HTML and its referenced assets must form a compatible release. Browser/CDN caching can mix versions if filenames and cache rules are poorly designed. An old index references app-old.js that was deleted during deployment. A user with cached HTML gets a blank page even though a fresh load works. Retaining versioned assets and controlling entry-point caching avoids this mixed release.", "technical": "Use content-hashed immutable assets, short-lived or revalidated entry HTML, atomic deployments and versioned API contracts. Check service-worker behavior if present, actual request URLs, cache headers and error telemetry. Distinguish a cached old page from a new deployment missing files. Keep rollback assets available for the required compatibility window.", "followups": [["Does hard refresh fix every user's architecture?", "It can confirm a cache symptom but is not a deployment design. Correct versioning and headers so ordinary users recover automatically."], ["Should source credentials enter the frontend bundle?", "No. Runtime credentials remain in the backend/Function environment; public build output is readable by visitors."]]}, {"id": "quiz-74cfa9b89b25", "topic": "systems", "lessonId": "systems-a2bd0be4ca", "tag": "Application development scenarios", "prompt": "Two clients read revision 7. One saves revision 8. What should the other's revision-7 write do?", "options": ["Reset all other users' sessions.", "Fail with a conflict unless a deliberate safe merge is applied.", "Silently overwrite revision 8.", "Always succeed because both users are authenticated."], "correct": 1, "explanation": "A write should detect whether someone changed the record after it was read. Do not silently overwrite a newer revision with an older copy. Both clients read revision 7. Client A writes revision 8. Client B submits expected revision 7 and must receive a conflict rather than overwrite A. PrepAtoZ uses revision checks for account progress.", "technical": "Use optimistic concurrency with a revision/version or ETag and an atomic compare-and-set update. A mismatch returns a conflict so the client can reload or merge intentionally. Transactions and appropriate isolation/locking can handle stronger invariants. Keep idempotency of retried requests separate from detecting competing edits.", "followups": [["Can the client compare versions before sending and guarantee safety?", "No. Another write can occur between comparison and update. The server/database must enforce the condition atomically."], ["Can you merge every JSON field automatically?", "Not safely. Notes, counters and state transitions have different semantics; use a domain-defined merge or ask for resolution."]]}, {"id": "quiz-208e737c053c", "topic": "systems", "lessonId": "systems-1e594bde0f", "tag": "Application development scenarios", "prompt": "Login responds successfully but the next API request has no cookie. What is the first boundary to inspect?", "options": ["Cookie acceptance and request credential/domain/path/SameSite behavior.", "The model's embedding dimension.", "Whether the password hash is displayed in the UI.", "Disabling all authorization checks permanently."], "correct": 0, "explanation": "Check whether the browser actually received and sent the intended session cookie. Authentication also depends on domain, path, HTTPS and server-side session validity. A frontend on one origin calls another without the required credential mode, so no cookie accompanies /api/progress. A successful login response alone does not prove subsequent requests carry an authenticated session.", "technical": "Inspect sanitized network status and Set-Cookie/Cookie behavior, SameSite, Secure, expiry, request credentials mode, origin and session lookup. Check server time and shared database configuration across instances. Do not log raw session tokens or weaken CSRF checks to hide a cookie issue. Cross-origin deployment requires an explicit supported credential/CORS design.", "followups": [["Should you move the session token into localStorage to bypass the problem?", "Not as an automatic fix. It changes the threat model and exposure to script access. Diagnose the cookie contract and preserve appropriate HttpOnly handling."], ["Why can one server accept the user while another rejects them?", "They may use different secrets/stores, clocks or configuration. Use shared durable session state and consistent runtime configuration."]]}, {"id": "quiz-7341797c9e67", "topic": "systems", "lessonId": "systems-294bdc60ff", "tag": "Application development scenarios", "prompt": "The generation provider is unavailable. Which fallback is defensible for a policy assistant?", "options": ["Retrying forever without a deadline.", "Sending confidential data to any unapproved provider.", "An explicitly labeled view of authorized evidence, if useful and supported by the task.", "Fabricating an answer so the UI never shows an error."], "correct": 2, "explanation": "Set time budgets and define which useful features can still work. An unbounded queue or endless retry loop only makes an outage larger. During an outage, a policy assistant can show authorized source passages with a clear generation-unavailable message. A payment agent must not fabricate a successful action or move to an unapproved endpoint.", "technical": "Use per-call deadlines within an end-to-end budget, bounded retries for classified transient failures, circuit breaking where appropriate and admission control. Provide a cited retrieved-evidence view or deferred job if it meets the task. Any fallback model must pass required quality, security and data-handling constraints; never silently downgrade a critical guarantee.", "followups": [["Should every failed request be retried three times?", "No. Classify failures, honor total deadlines and account for idempotency and load. Invalid requests and denied permissions need correction rather than repetition."], ["Is an evidence-only response always safe?", "No. The evidence must still be authorized, applicable and clearly presented without implying an evaluated generated conclusion."]]}]}, "ml": {"title": "ML foundations", "description": "Missing values, outliers, model selection, evaluation and production debugging", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-f3322a988b56", "topic": "ml", "lessonId": "ml-6a41878543", "tag": "Statistical foundations", "prompt": "For [1,2,3,4,100], what are the mean and median?", "options": ["Mean 3, median 22.", "Both 22 because outliers are ignored.", "Both 100 because it is the maximum.", "Mean 22, median 3."], "correct": 3, "explanation": "Mean is the arithmetic average; median is the middle value. Variance measures squared spread around the mean, and standard deviation brings spread back to the original units. For [1,2,3,4,100], mean=22 and median=3. The mean is pulled toward the extreme value. If these are legitimate transaction amounts, changing 100 to 4 silently destroys real business information.", "technical": "For independent observations, the usual sample variance divides squared deviations by n-1 to estimate population variance under its assumptions. Population variance divides by n. Median resists isolated extremes more than mean. Heavy tails and multimodal data require distribution inspection rather than reporting one summary alone.", "followups": [["Is median always the best imputation?", "No. It is a robust baseline for skewed numeric features, but missingness patterns, feature meaning and model behavior matter. Fit it within the training fold."], ["Does standard deviation assume data is normal?", "It can be calculated without normality. Interpreting fixed sigma ranges as particular coverage probabilities requires distributional assumptions."]]}, {"id": "quiz-8a366983d452", "topic": "ml", "lessonId": "ml-943c622234", "tag": "Statistical foundations", "prompt": "What does a classic central limit theorem say becomes approximately normal under its assumptions?", "options": ["The classification labels themselves.", "The standardized sampling distribution of the mean.", "Every individual raw observation.", "Any biased dataset after exactly 30 rows."], "correct": 1, "explanation": "The law of large numbers concerns an average settling toward its expected value. A central limit theorem concerns the distribution of a suitably scaled average around that value. Purchase amounts may stay strongly right-skewed, while means from many sufficiently large independent samples become approximately normal. Sampling only premium customers still estimates the wrong population even with a million rows.", "technical": "In the classic independent identically distributed finite-variance setting, sqrt(n)*(sample_mean-mu)/sigma converges in distribution to a standard normal. This does not make the raw data normal. Dependence, selection bias and heavy tails can undermine naive normal intervals; there is no universal n=30 guarantee.", "followups": [["Does more data remove sampling bias?", "No. Large biased samples can estimate the wrong population very precisely. Inspect coverage, selection and the deployment population."], ["What if records belong to the same customer?", "They may be dependent. Use group-aware estimation/splitting and an uncertainty method suited to the sampling unit, such as a cluster bootstrap when justified."]]}, {"id": "quiz-544ce9a0daa5", "topic": "ml", "lessonId": "ml-4e86a044aa", "tag": "Statistical foundations", "prompt": "Among 90 true-positive alerts and 495 false-positive alerts, what is precision?", "options": ["90/585, about 15.4%.", "90%, because recall is 90%.", "495/585, about 84.6%.", "99%, because most cases are legitimate."], "correct": 0, "explanation": "Bayes' theorem updates a prior belief using observed evidence. A seemingly strong detector can still produce many false alarms when the event is rare. The detector finds 90 of 100 frauds but also flags 495 legitimate cases. Only about 15.4% of its alerts are fraud. This illustrative arithmetic explains why an analyst queue can be overwhelmed despite high recall.", "technical": "P(A|B)=P(B|A)P(A)/P(B). Positive predictive value depends on sensitivity, specificity and prevalence. A model's recall alone does not determine how trustworthy a positive prediction is. Estimate using deployment-like base rates and account for uncertainty or changing prevalence.", "followups": [["Can balanced-test precision predict production precision?", "Not directly when prevalence differs. Reweight or evaluate a representative sample and report the assumed base rate."], ["Should you optimize only recall?", "No. Choose a threshold using missed-event cost, false-alarm burden, capacity and policy constraints. Show the trade-off curve rather than a single unsupported target."]]}, {"id": "quiz-152f2ea7322d", "topic": "ml", "lessonId": "ml-806d22966d", "tag": "Numerical interview drills", "prompt": "With TP=40, FP=10 and FN=20, what is F1?", "options": ["40/50, exactly precision.", "40/60, exactly recall.", "80/110, approximately 0.727.", "0.97 because that is overall accuracy."], "correct": 2, "explanation": "Each metric asks a different question: whether alerts are reliable, whether positives are found, whether negatives are rejected, or how often all predictions match. The model is 97% accurate yet misses one-third of positives. If positives are critical equipment failures, the 97% headline hides a costly recall problem. Use business-sensitive error analysis rather than comparing headline accuracy alone.", "technical": "TP=positive predicted positive; FP=negative predicted positive; FN=positive predicted negative; TN=negative predicted negative. Precision=TP/(TP+FP), recall=TP/(TP+FN), specificity=TN/(TN+FP), F1=2TP/(2TP+FP+FN), accuracy=(TP+TN)/N. Declare positive class, averaging and handling of zero denominators.", "followups": [["When do micro and macro averages differ?", "Macro averages per-class scores equally; micro pools counts, favoring common classes. For single-label multiclass classification, micro F1 equals accuracy, so minority recall needs separate reporting."], ["Does F1 include true negatives?", "No. Its formula uses TP, FP and FN. It does not measure calibration, true-negative burden or every business cost."]]}, {"id": "quiz-d3f46361568e", "topic": "ml", "lessonId": "ml-f00bcf671f", "tag": "Numerical interview drills", "prompt": "For half-squared loss with x=2,y=5,w=1,b=0 and learning rate 0.1, what is the simultaneous update?", "options": ["w=1.6 and b=0.3.", "w=0.4 and b=-0.3.", "w=6 and b=3.", "w stays 1 because linear regression has no gradient."], "correct": 0, "explanation": "Gradient descent changes a weight a little in the direction that lowers the chosen loss. Learning rate controls the step size. With new w=1.6 and b=0.3, the same sample predicts 3.5, closer to 5. One improving sample update does not establish generalization; check training dynamics and validation performance.", "technical": "For one sample, prediction wx+b and loss (1/2)*(prediction-y)^2 give gradients (prediction-y)*x and (prediction-y). Update both using gradients evaluated at the old parameters. Batch averaging, loss scaling and optimizer state change exact numerical updates; state your convention before calculating.", "followups": [["What if the loss omits the one-half?", "Both gradients gain a factor of two. Equivalent learning-rate scaling can compensate, but the written formula must match the calculation."], ["Why can a very large learning rate diverge?", "The step can overshoot a low-loss region and amplify errors. Inspect scaling, gradients and schedules rather than assuming more steps always help."]]}, {"id": "quiz-fdc4e6cc71ed", "topic": "ml", "lessonId": "ml-9200fdd55a", "tag": "Algorithms and decisions", "prompt": "What should train a stacking meta-model to reduce leakage?", "options": ["The final test labels during feature engineering.", "Random labels to guarantee independence.", "Out-of-fold predictions from the base models.", "Only base predictions on the same rows each base model fit."], "correct": 2, "explanation": "Bagging combines models trained on varied samples; boosting builds models that improve a running ensemble; stacking trains another model to combine base predictions. If a base model's training predictions feed a stacker, the stacker sees unrealistically easy inputs. Generate predictions from folds where that row was not used to fit the base model, then train the meta-model on those predictions.", "technical": "Random forests combine bootstrapped trees and random feature subsets to reduce correlated variance. Gradient boosting fits successive learners to a loss-related negative-gradient target. A stacker must train on out-of-fold base predictions to avoid leakage. Ensemble choice depends on data size, noise, latency, interpretability and deployment constraints.", "followups": [["Is boosting always better on noisy labels?", "No. Excessive capacity or iterations can fit noise. Tune regularization and early stopping with suitable validation and investigate label quality."], ["Does adding more trees always reduce latency?", "No. Serving cost can grow with ensemble size. Measure prediction latency, memory and quality at the chosen configuration."]]}, {"id": "quiz-4095d771afa4", "topic": "ml", "lessonId": "ml-2fbaba53b5", "tag": "Algorithms and decisions", "prompt": "A model has high AUC but its 0.8 predictions succeed only 40% of the time. What is wrong?", "options": ["Its probability calibration is poor despite useful ranking.", "Its ranking must necessarily be random.", "Its accuracy must be exactly 80%.", "Temperature alone proves the business risk is correct."], "correct": 0, "explanation": "A calibrated model's 80% predictions should be correct about 80% of the time over comparable cases. Ranking quality and trustworthy probability values are different properties. A credit-risk model ranks cases well but outcomes occur in only 40% of cases scored near 0.8. A threshold based on the raw probabilities can misprice risk even if ROC-AUC looks strong. Calibrate and evaluate on deployment-like cases.", "technical": "Sigmoid/Platt-style calibration fits a parametric mapping; isotonic fits a nondecreasing flexible mapping and usually needs more calibration data. Fit calibration on held-out or cross-validated predictions, not the same overfit training outputs. Assess reliability plots and proper scoring rules such as log loss or Brier score with subgroup and sample-size checks.", "followups": [["Can calibration preserve ranking?", "Monotone mappings generally preserve ordering, though ties can be introduced. Calibration and discrimination should still be reported separately."], ["Can you calibrate once forever?", "No. Changes in prevalence, feature distribution or the base model can break the mapping. Monitor reliability and recalibrate using suitable new labeled data."]]}, {"id": "quiz-deddaa536864", "topic": "ml", "lessonId": "ml-525a778304", "tag": "Algorithms and decisions", "prompt": "What can a SHAP attribution establish on its own?", "options": ["A guarantee of fairness across all groups.", "Proof that the training labels are correct.", "An explanation of a model prediction relative to stated background assumptions.", "A causal effect of changing the feature in the real world."], "correct": 2, "explanation": "Feature importance explains aspects of a model's predictions, not necessarily what would happen if the world were changed. Correlated features can share or hide importance. Both postcode and income correlate with loan outcomes. Shuffling postcode while leaving correlated features intact may understate its joint information, while the model can still encode sensitive proxies. A small reported importance is not a fairness certificate.", "technical": "Permutation importance measures score degradation after disrupting a feature on representative evaluation data. SHAP attributes a prediction relative to a background/reference distribution under chosen dependence assumptions. Correlation, leakage and unstable data can distort interpretation. Use held-out performance, subgroup checks and domain review; causal intervention claims require separate assumptions and evidence.", "followups": [["Should you calculate importance on training data only?", "No. Held-out evaluation helps distinguish generalizable use from overfit patterns. Document the chosen data distribution and scoring metric."], ["Can SHAP justify rejecting a customer automatically?", "It is an explanatory aid, not proof of policy validity or causal fairness. Decisions need appropriate governance, error review and the applicable business process."]]}, {"id": "quiz-24ed78dcb0d9", "topic": "ml", "lessonId": "ml-c05a87995d", "tag": "Algorithms and decisions", "prompt": "Where should SMOTE run during cross-validation?", "options": ["On the full dataset before making folds.", "On the test labels to balance the final score.", "On production traffic with no labels or validation.", "Inside each training fold only."], "correct": 3, "explanation": "These methods change how much rare classes influence learning. They do not create trustworthy labels or remove the need for representative evaluation. If you synthesize examples before splitting, related real/synthetic points can enter both train and test. This leaks information and inflates metrics. A pipeline should split first and fit resampling only on each training fold.", "technical": "Class weights modify the loss; undersampling discards some majority examples; oversampling repeats or synthesizes minority examples. SMOTE interpolates in a feature neighborhood and can be inappropriate for categorical, temporal or constrained features without a suitable method. Apply resampling only inside training folds, then evaluate on untouched deployment-like data and calibrate if needed.", "followups": [["Does a 50:50 training set mean production precision is measured at 50:50?", "No. Report evaluation at the real or explicitly modeled deployment base rate. Training prevalence and deployment prevalence have different purposes."], ["When is undersampling dangerous?", "When it removes important majority subgroups or rare legitimate behavior. Compare subgroup errors and retain representative difficult negatives."]]}, {"id": "quiz-bc8927ffe353", "topic": "ml", "lessonId": "ml-cf79d2d2f0", "tag": "Algorithms and decisions", "prompt": "Which property fits DBSCAN?", "options": ["A guarantee that every noise point is malicious.", "No sensitivity to feature scaling or neighborhood parameters.", "Density-connected groups with possible noise labels and no required cluster count.", "A mandatory preset K and only spherical centroids."], "correct": 2, "explanation": "K-means assigns points to a chosen number of centroid-based groups. DBSCAN connects dense neighborhoods and can label isolated points as noise. Two crescent-shaped groups can be split poorly by a nearest-centroid boundary. A suitable DBSCAN neighborhood can follow the connected shapes, but one eps may fail when one group is much denser than the other.", "technical": "K-means minimizes within-cluster squared Euclidean distance and suits appropriately scaled compact clusters. DBSCAN uses eps and min_samples, handles some non-spherical shapes and does not require a cluster count, but varying density and high-dimensional distance concentration complicate tuning. Neither algorithm's clusters automatically correspond to meaningful business categories.", "followups": [["Is every DBSCAN noise point a fraud?", "No. Noise means sparse under the chosen features and parameters. Validate business meaning and review false alarms."], ["How do you evaluate clustering without labels?", "Use stability, domain utility and suitable internal metrics while checking their geometric assumptions. A high silhouette score is not proof of operational value."]]}, {"id": "quiz-d3e9f493b1db", "topic": "ml", "lessonId": "ml-70947e27e0", "tag": "Production scenarios", "prompt": "Which validation best matches a future demand forecasting task?", "options": ["Rolling-origin splits with features available before each cutoff.", "Randomly mix all dates and use final corrected future totals.", "Fit preprocessing on all dates before validation.", "Drop every zero-demand item to improve MAPE silently."], "correct": 0, "explanation": "Make each validation run imitate what was knowable at the time of prediction. Future sales, later corrections and revised promotional data must not leak backward. A feature computed from the final week's total sales cannot predict Monday of that same week. Instead, use a lagged window that ends before the forecast cutoff and promotion plans actually published by then.", "technical": "Use rolling-origin splits, point-in-time feature joins and prediction-time availability rules. Fit imputation/scaling within each training window. Include naive seasonal baselines, demand segments, horizons and intermittent-demand cases. Distinguish labels unavailable yet from true zero sales. Set retraining and evaluation schedules around label delay.", "followups": [["Why not random train/test split?", "Nearby time observations and future regime information can leak across the split, producing an optimistic estimate of future forecasting quality."], ["Why can MAPE fail here?", "Zero or near-zero demand makes its denominator unstable or undefined. Choose metrics and business costs that remain meaningful for those items."]]}, {"id": "quiz-6724b409729e", "topic": "ml", "lessonId": "ml-03f3737221", "tag": "Production scenarios", "prompt": "A global metric improves while a critical cohort regresses sharply. What should decide rollout?", "options": ["The global average alone.", "Removing the cohort from evaluation.", "Deploying everywhere to gather unbounded evidence of harm.", "Cohort error budgets, uncertainty and consequences alongside overall results."], "correct": 3, "explanation": "An average can hide harm to a minority group. Inspect the affected slice, measurement uncertainty and decision consequences before approving the release. Overall recall rises from 85% to 88%, while recall for a small language cohort falls from 70% to 40%. The weighted average improves because most cases use another language; that does not resolve the regression.", "technical": "Define relevant cohorts and critical error budgets before release. Compare baseline and candidate on the same cases, examine sample size/confidence intervals and rule out data/label changes. Use stratified monitoring and human review where appropriate. A canary should have stop conditions for critical slices, not just global latency and accuracy.", "followups": [["Does equal accuracy prove fairness?", "No. Error types, base rates, calibration, access and decision costs can differ. Choose metrics with domain and policy context."], ["What if the cohort is too small for a reliable estimate?", "Report uncertainty, collect representative data and constrain rollout or route sensitive cases for review rather than inventing confidence."]]}, {"id": "quiz-91df642f7608", "topic": "ml", "lessonId": "ml-9619b4dbe5", "tag": "Production scenarios", "prompt": "Training uses dollars but serving sends cents. What is the main failure?", "options": ["Insufficient model temperature.", "A problem fixed solely by increasing class weights.", "Training-serving feature skew caused by an inconsistent unit contract.", "A necessary consequence of more data."], "correct": 2, "explanation": "The model may receive different inputs in production even when its weights are unchanged. Compare feature definitions and point-in-time examples across both paths. Training divides amounts by 100 to convert cents to dollars; serving passes cents directly. A $20 purchase is seen as 2000 rather than 20. Scaling the API does not repair this deterministic feature bug.", "technical": "Trace raw inputs, schema versions, preprocessing artifacts, time windows, category handling and freshness. Replay sanitized production examples through the training transform and compare values before scoring. Share versioned transformation code or contracts and monitor missingness/range/distribution. Feature stores help consistency only if access, computation and timestamps are correct.", "followups": [["Is all drift training-serving skew?", "No. Skew is a mismatch in representation or pipeline semantics; population drift can occur even with identical transformations. Diagnose both."], ["Would retraining fix a unit-conversion bug?", "It could conceal it temporarily but leaves an inconsistent contract. Correct the transform and validate affected predictions before retraining if needed."]]}, {"id": "quiz-9132c46c4b9e", "topic": "ml", "lessonId": "ml-d1b79d923b", "tag": "Model selection and statistical reasoning", "prompt": "Why must imputation statistics be fitted inside each training fold?", "options": ["Because median cannot be computed on training data.", "So validation/test information does not influence the learned preprocessing.", "Because using all data is always required for honest validation.", "To make null values disappear from production automatically."], "correct": 1, "explanation": "Preprocessing parameters are part of the trained pipeline. Fitting them before splitting can leak the evaluation distribution and make validation optimistic.", "technical": "Audit feature timestamps, post-outcome columns, duplicate families, whole-dataset preprocessing and label-informed sampling. Use ablation tests, temporal evaluation and suspicious-feature review. A field created after ticket resolution is unavailable at ticket creation even if the training table includes it. Pipeline-based fold fitting prevents many preprocessing leaks.", "followups": [["Is high accuracy proof of leakage?", "No. It is a reason to investigate. Validate feature availability and the deployment-matched split."], ["Can oversampling cause leakage?", "Yes, if performed before splitting. Synthetic observations can share source information across folds. Resample training folds only."]]}, {"id": "quiz-88c7da5186a8", "topic": "ml", "lessonId": "ml-4dd0948013", "tag": "Outliers, anomalies and robust treatment", "prompt": "Using Q1=10 and Q3=20, what is the usual upper 1.5-IQR fence?", "options": ["35, since IQR=10 and 20+1.5*10=35.", "15, because it is the median of the quartiles.", "30, because all fences are Q1+Q3.", "100, because percentiles are percentages."], "correct": 0, "explanation": "The IQR rule flags values for investigation under a distributional heuristic. It does not establish that every flagged value is erroneous or should be deleted.", "technical": "Start with range, unit, duplicate and timestamp checks; inspect histograms, boxplots, quantiles and cohort-aware scatterplots. IQR fences use Q1-1.5*IQR and Q3+1.5*IQR. Z-scores rely on mean and standard deviation and can be misleading with heavy tails; median absolute deviation is a robust alternative. For multivariate relationships compare Isolation Forest, LOF or domain rules. Fit thresholds on training/reference data and validate flags with experts.", "followups": [["Is every point outside an IQR fence wrong?", "No. It is an investigation candidate. Valid heavy-tailed distributions naturally produce extreme observations."], ["Why can univariate tests miss an outlier?", "Height and weight can each be plausible but unusual together. Multivariate detection considers the relationship."], ["Is an absolute z-score above three a universal rule?", "No. It is a distribution-dependent heuristic. Validate false alerts, tail behavior and domain costs."]]}]}, "aws": {"title": "AWS & scaling", "description": "Compute, storage, networking, queues and practical cloud architecture", "reference": "Worked examples are illustrative, not measured project results. Check provider and framework version-specific behavior against the linked primary documentation.", "questions": [{"id": "quiz-dd8401bd0dbc", "topic": "aws", "lessonId": "aws-464a14f0a7", "tag": "Data and networking", "prompt": "Which storage is the usual fit for uploaded document objects accessed by key?", "options": ["S3 object storage.", "A browser's session cookie.", "An EC2 instance's RAM only.", "An SQS visibility timeout."], "correct": 0, "explanation": "S3 stores objects through an API; EBS provides block volumes typically attached to EC2; EFS provides a managed shared file system. They expose different access and consistency interfaces. Store uploaded manuals and immutable ingestion artifacts in S3. Put an EC2 database's storage on an appropriately designed block-storage setup. Use a shared file system only when the application genuinely needs compatible shared-file semantics.", "technical": "Choose by object versus filesystem access, sharing needs, throughput, latency, AZ design and cost. An EBS volume is not a general multi-writer shared application database. EFS is not automatically the right database storage. S3 object keys are not POSIX file paths, and an object overwrite is not a transactional row update.", "followups": [["Can you keep a Netlify SQLite file in its deployment folder for durable shared users?", "No. A serverless deployment's filesystem is not a shared durable database. Use a supported persistent database service; this app uses remote libSQL-compatible storage."], ["Does S3 remove the need for a metadata database?", "No. Queryable workflow state, ownership and transactional constraints often belong in a database, while large immutable blobs remain in object storage."]]}, {"id": "quiz-9107152a4de8", "topic": "aws", "lessonId": "aws-88b85fe931", "tag": "Data and networking", "prompt": "After adding an S3 VPC endpoint, what remains required?", "options": ["No IAM policy because the network is private.", "A public IP on every document.", "Disabling all bucket encryption.", "Correct routing and explicit IAM/bucket-policy authorization."], "correct": 3, "explanation": "A NAT gateway provides outbound connectivity for suitable private-subnet traffic. VPC endpoints offer service-specific private connectivity paths, depending on endpoint type and service support. A worker reading a large S3 corpus may use an S3 gateway endpoint instead of routing that service traffic through NAT. It still needs an allowed IAM identity and compatible bucket policy.", "technical": "Gateway endpoints support particular services such as S3 and DynamoDB using route-table integration. Interface endpoints use private IPs and service-specific configuration. Compare regional support, DNS, endpoint policies, security groups where applicable, routing and cost. Neither endpoint selection nor private networking grants IAM permissions automatically.", "followups": [["Does a private subnet guarantee no data exfiltration?", "No. Egress routes, credentials, endpoints and application behavior determine reachable destinations and permitted actions."], ["Can an endpoint solve a denied S3 request?", "Only if the issue is connectivity or an endpoint/bucket-policy boundary. IAM or encryption-key authorization failures require inspecting those policies too."]]}, {"id": "quiz-8b634d1559a1", "topic": "aws", "lessonId": "aws-1cb2932e78", "tag": "Data and networking", "prompt": "A model process is running but still loading weights. Which status is appropriate?", "options": ["Authorized for every user because it started.", "Alive, but not ready to accept inference work.", "Ready because a process ID exists.", "Dead and requiring an infinite restart loop."], "correct": 1, "explanation": "Readiness asks whether a process should receive work; liveness asks whether it should be restarted. A load-balancer check controls which registered targets receive traffic under that balancer's rules. A model-serving container is alive while loading weights but not ready for inference. Route traffic only after a representative initialization check succeeds, then drain accepted streams before termination.", "technical": "Design checks around initialization, critical dependencies, draining and failure modes. A readiness failure should not necessarily trigger a restart storm. Container/orchestrator probes and ALB health checks are distinct mechanisms. Avoid making every replica restart just because a shared database is briefly unavailable.", "followups": [["Should liveness execute a costly full model inference every second?", "Usually no. It can overload serving and cause false failures. Separate lightweight process health from readiness and periodic deeper synthetic checks."], ["What if all targets are unhealthy?", "Inspect the actual load balancer's documented behavior and implement an explicit outage path. Do not assume health checks alone guarantee traffic is safely rejected."]]}, {"id": "quiz-622a1ca9f14c", "topic": "aws", "lessonId": "aws-a0b6023c85", "tag": "Queues and orchestration", "prompt": "A FIFO worker performs a payment then crashes before acknowledgement. What protects against a duplicate payment?", "options": ["Assuming FIFO atomically commits the payment with deletion.", "Generating a new payment ID on every retry.", "Increasing the LLM temperature.", "Durable business idempotency tied to the same operation ID."], "correct": 3, "explanation": "Standard queues can deliver duplicates. FIFO adds ordering within message groups and deduplication behavior, but a business action can still be repeated if your consumer's success is not safely recorded. A worker charges an account and crashes before deleting the message. Redelivery must look up the same payment operation ID rather than create a second charge. Queue deduplication is not a substitute for business idempotency.", "technical": "Design idempotent consumers with durable operation identities. FIFO deduplication and ordering have documented scope and limits; they do not atomically commit an external payment or document index update with queue acknowledgement. Visibility timeout, deletion and retry behavior remain operational concerns. Message group design affects parallelism.", "followups": [["Why can one FIFO message group become a bottleneck?", "Ordering within that group limits concurrent progression. Partition groups by an appropriate ordering key without breaking the required business order."], ["Does a DLQ prove a message is permanently invalid?", "No. It records exhausted delivery/processing attempts under a policy. Diagnose transient dependency issues, poison payloads and version mismatches before replay."]]}, {"id": "quiz-0c8c2bde80c7", "topic": "aws", "lessonId": "aws-1949c859a3", "tag": "Queues and orchestration", "prompt": "With 600 queued jobs, 10 jobs/s arriving and 20 jobs/s processed, approximate drain time is what?", "options": ["60 seconds under steady-rate assumptions.", "30 seconds, ignoring new arrivals.", "6000 seconds regardless of processing rate.", "Zero because Auto Scaling always clears queues instantly."], "correct": 0, "explanation": "Consumers must process work faster than it arrives to shrink a backlog. More workers help only until a shared dependency becomes the bottleneck. At two jobs per second per worker, ten workers nominally provide 20 jobs/s. A provider quota capped at 12 jobs/s changes the net drain rate to only 2 jobs/s, so the same backlog takes about 300 seconds under these assumptions.", "technical": "If arrival rate is lambda, sustainable service rate mu must exceed lambda. Approximate drain time for backlog B under steady rates is B/(mu-lambda). Estimate concurrency from measured service times and capacity constraints, not CPU alone. Backlog age, model quotas, database connections and fairness matter; workload variance makes simple averages optimistic.", "followups": [["Why scale on oldest-message age?", "It exposes user waiting time that queue length alone can hide. Combine age, arrival rate, service rate and failure/retry counts."], ["What if a small tenant floods the queue?", "Apply per-tenant budgets, fair scheduling or partitioning and admission limits. Unlimited concurrency can amplify dependency throttling."]]}, {"id": "quiz-44e1c4367b85", "topic": "aws", "lessonId": "aws-1039185d05", "tag": "Queues and orchestration", "prompt": "A failed workflow step has already sent an email. What does a catch handler guarantee?", "options": ["Exactly-once execution of all downstream systems.", "That no further monitoring is necessary.", "Only the configured failure path; it cannot automatically unsend the email.", "Full rollback of every external effect."], "correct": 2, "explanation": "An orchestrator records steps and routes failures. Retrying a step repeats work; compensation is a separate business action intended to address a completed effect. A report workflow reserves capacity, creates a document and emails a link. If email fails, deleting the document is not always the right compensation. The business may prefer retrying delivery or surfacing an incomplete-delivery status.", "technical": "Classify transient versus permanent errors and apply bounded backoff with jitter and a whole-workflow time budget. Persist operation identity across retries. A catch path can route to cleanup or human review, but does not automatically roll back remote services. Choose workflow/service modes based on documented execution, history, limits and cost.", "followups": [["Should validation errors be retried forever?", "No. A deterministic invalid payload needs correction or a dead-letter/manual path. Repeating it consumes capacity without progress."], ["Can compensation perfectly undo every action?", "No. A sent email or disclosed document cannot be unsent by deleting state. Model irreversibility explicitly."]]}, {"id": "quiz-19ac9650043b", "topic": "aws", "lessonId": "aws-cda9e94929", "tag": "Identity and operations", "prompt": "An identity allow conflicts with an applicable explicit deny. What wins?", "options": ["Whichever statement the LLM reads first.", "The explicit deny.", "The policy with the longest text.", "The identity allow always overrides all restrictions."], "correct": 1, "explanation": "Authorization is evaluated across relevant policy boundaries. An explicit deny can block an action even when another policy appears to allow it. A worker's identity policy allows s3:GetObject, but a bucket policy explicitly denies requests outside an approved network path. Adding another identity allow does not override that deny.", "technical": "Inspect the actual principal, assumed role session, action, resource, conditions and applicable policy types. Permissions boundaries, organization controls and service-specific rules can limit identity grants. Resource-based access and cross-account behavior need their own evaluation. Least privilege means a narrow documented action/resource set, not simply avoiding administrator names.", "followups": [["Why prefer roles over embedding long-lived access keys?", "Roles provide scoped temporary credentials through supported identity flows and reduce static-key distribution. Their trust and permission policies still require care."], ["Does KMS permission follow automatically from S3 read access?", "Not necessarily. An encrypted object can require compatible key permissions and key policy. Inspect both the storage and encryption authorization paths."]]}, {"id": "quiz-c16e9714d2c1", "topic": "aws", "lessonId": "aws-c6b44e3652", "tag": "Identity and operations", "prompt": "Why might a read replica return an older value immediately after a write?", "options": ["The database must be unencrypted.", "Load balancing changes the committed transaction's value.", "Replication lag can make the read eventually consistent.", "Every replica is always synchronously identical by definition."], "correct": 2, "explanation": "Availability designs prepare for failures; replicas can serve additional reads under supported configurations. A copy of data is not automatically a backup or a strongly consistent read endpoint. A recently completed purchase may not yet appear on an asynchronously replicated read target. Route read-after-write queries appropriately or design a user-visible eventual-consistency policy.", "technical": "RDS deployment types differ: a traditional Multi-AZ instance standby is not a read-scaling target, while Multi-AZ DB clusters expose different readable-instance behavior. Read replicas generally have replication-lag and promotion considerations. Specify engine and deployment type, connection recovery, transaction semantics and RPO/RTO instead of saying all replicas behave identically.", "followups": [["Can a replica replace backups?", "No. Logical deletion or corruption can replicate. Keep tested backups and restoration procedures with required retention and recovery objectives."], ["Why can more API replicas hurt RDS?", "Each may open a connection pool. Total connections can exceed database capacity; bound pools, use suitable pooling/proxies and fix expensive queries."]]}, {"id": "quiz-db7618e0db5f", "topic": "aws", "lessonId": "aws-5ee0b67b3c", "tag": "Production scenarios", "prompt": "A queued ingestion workload is throttling inference. What is the best first scaling boundary?", "options": ["Increase consumers without any cap or quota check.", "Remove the queue and retry synchronously forever.", "Generate a new operation ID for every delivery.", "Bound consumer concurrency to measured downstream capacity and make retries idempotent."], "correct": 3, "explanation": "Limit work to the model's capacity and make repeated messages safe. A queue absorbs bursts but cannot create unlimited downstream quota. A batch contains nine successful jobs and one failed job. Repeating all ten without durable job IDs can duplicate nine effects. Correct partial-batch handling and idempotency reduce amplification.", "technical": "Measure invocation concurrency, batch behavior, timeouts, visibility, retry rate and provider throttle response. Cap event-source/worker concurrency, use per-operation idempotency, configure partial-batch failure handling where supported and route exhausted failures deliberately. Keep a total retry budget and admission policy; separate deterministic bad payloads from transient throttles.", "followups": [["Should every timeout trigger a new job ID?", "No. Preserve the original logical identity and reconcile unknown outcomes; a timeout does not prove no remote effect occurred."], ["What should happen before DLQ replay?", "Classify the failure, repair the cause, preserve operation IDs and replay at bounded rate. Blind replay can recreate the outage."]]}, {"id": "quiz-9259b85a73eb", "topic": "aws", "lessonId": "aws-83baa457ca", "tag": "Production scenarios", "prompt": "Local owner credentials work, but the runtime task role gets AccessDenied. What should you inspect first?", "options": ["Change the UI font to reduce request size.", "The runtime principal and denied action/resource across applicable policies.", "Grant administrator access to every service permanently.", "Disable encryption for all stored data."], "correct": 1, "explanation": "Identify the actual cloud identity and the specific denied action. Do not solve an unknown permission failure by granting administrator access. Local development uses an owner account while an ECS task uses a narrow task role. The runtime role can read an S3 object but cannot decrypt its KMS key. Granting unrelated EC2 permissions would not address the missing action.", "technical": "Inspect sanitized error context, role/session identity, region, resource ARN, trust policy, identity/resource policies, explicit denies and encryption-key requirements. Use available audit logs and policy analysis tools. Compare local credentials with runtime role credentials and check expiry/assumption flow. Apply the smallest justified permission change and retest both allowed and denied cases.", "followups": [["Should you paste the access token into logs?", "No. Log principal identifiers, request IDs and sanitized action/resource metadata needed for diagnosis, not raw credentials."], ["Could the error be networking instead?", "Separate transport/connectivity failures from explicit authorization responses. Check request IDs and the actual service response before changing network or IAM settings."]]}, {"id": "quiz-a668161b0624", "topic": "aws", "lessonId": "aws-39e63fcbe3", "tag": "AWS vocabulary: start with the building blocks", "prompt": "Which service gives direct control of a virtual server's operating system?", "options": ["An IAM policy document.", "EC2.", "S3 object storage.", "SQS messaging."], "correct": 1, "explanation": "EC2 provides virtual compute instances. That control brings responsibilities for operating-system configuration, deployment, patching, networking and availability design.", "technical": "Choose an instance family for CPU, memory, network or GPU needs, then configure an image, storage, networking, IAM role and lifecycle management. Use immutable images or automation, health checks, patching and recovery. EC2 gives control but leaves more operational work than a managed container/serverless path.", "followups": [["Is stopping an instance the same as terminating it?", "No. Lifecycle and attached-storage behavior differ. Check volume deletion settings and persistence before changing instance state."], ["Does one powerful EC2 instance provide high availability?", "No. It remains one failure domain. Use redundant capacity and external durable state where the availability requirement calls for it."]]}, {"id": "quiz-f5d4907d9dd2", "topic": "aws", "lessonId": "aws-18c62f4491", "tag": "AWS vocabulary: start with the building blocks", "prompt": "What is the difference between a load balancer and Auto Scaling?", "options": ["Auto Scaling guarantees downstream database capacity.", "A load balancer distributes traffic; Auto Scaling adjusts configured capacity based on policies.", "Both are identical names for S3 replication.", "A load balancer always creates unlimited backend capacity."], "correct": 1, "explanation": "Traffic distribution and capacity adjustment are separate. Both must respect readiness, startup time, quotas and bottlenecks such as model endpoints or connection pools.", "technical": "An Application Load Balancer works at the application layer with HTTP-oriented routing. A Network Load Balancer addresses transport-layer needs. Configure target health, TLS, timeouts and draining. A load balancer distributes available work but does not create new application capacity or fix a saturated database.", "followups": [["Do WebSockets or streaming responses need special attention?", "Yes. Idle timeouts, connection draining and reconnect/resume behavior must fit the application. Test rolling releases with active streams."], ["Are sticky sessions a substitute for external state?", "No. They may support a specific routing requirement, but shared durable state and recovery are still needed when targets fail."]]}]}, "mcp": {"id": "mcp", "title": "MCP", "description": "Protocol basics, tool contracts, authorization and production recovery. Choose one answer, check the explanation, then continue.", "reference": "Questions about version-dependent details use the 2025-11-25 protocol specification; check your actual SDK and negotiated version.", "sources": [{"title": "MCP architecture", "url": "https://modelcontextprotocol.io/docs/learn/architecture"}, {"title": "MCP 2025-11-25 authorization", "url": "https://modelcontextprotocol.io/specification/2025-11-25/basic/authorization"}, {"title": "MCP 2025-11-25 transports", "url": "https://modelcontextprotocol.io/specification/2025-11-25/basic/transports"}], "questions": [{"id": "mcp-roles", "tag": "Foundations", "prompt": "Which statement best describes an MCP host, client and server?", "options": ["The host coordinates clients, and each client communicates with a server exposing capabilities.", "Every MCP server must host an LLM.", "The client is always a browser and the server is always a database.", "The protocol replaces the application's authorization system."], "correct": 0, "explanation": "The host is the AI application. It manages client connections to servers that expose capabilities. A server need not run a model, and the application still owns authorization and orchestration.", "technical": "Separate protocol participants from deployment processes. A host can connect to multiple servers through its client components; local and remote placement do not change each participant's responsibility.", "followups": [["Can one host use several servers?", "Yes. Keep connection lifecycle, identity and capability scope clear for each server."], ["Does an MCP server have to be remote?", "No. A local subprocess can expose capabilities, while a remote service can support network clients."]], "topic": "mcp", "lessonId": "mcp-roles"}, {"id": "mcp-primitives", "tag": "Foundations", "prompt": "How do tools, resources and prompts differ in MCP?", "options": ["They are three names for executable functions.", "Tools expose callable operations, resources expose contextual data, and prompts expose reusable interaction templates.", "Resources can always modify databases.", "Prompts grant authorization to use every tool."], "correct": 1, "explanation": "These primitives serve different roles. A resource is not automatically an action, and a prompt template is not permission to execute a tool. The host decides how to present and use exposed capabilities.", "technical": "Describe actual schemas, resource identifiers and prompt arguments rather than assuming every primitive has identical discovery or invocation behavior. Supported features depend on the selected protocol and SDK.", "followups": [["Can a read-only lookup be a tool?", "Yes. Tools can be read-only or effectful. The server must enforce the actual behavior and access policy."], ["Do templates make output safe?", "No. Validate requests, evidence and tool effects independently of template wording."]], "topic": "mcp", "lessonId": "mcp-primitives"}, {"id": "mcp-jsonrpc", "tag": "Protocol", "prompt": "Which message format underlies MCP protocol communication?", "options": ["An arbitrary unstructured chat transcript.", "SQL statements sent directly to every server.", "JSON-RPC messages with the selected transport's framing rules.", "Only binary GPU tensors."], "correct": 2, "explanation": "MCP uses JSON-RPC message structures. Transport framing, lifecycle and the supported protocol version still matter; a plain REST endpoint returning JSON is not automatically a compliant MCP server.", "technical": "Distinguish requests, responses and notifications. Preserve request IDs and valid error structures, and follow the chosen transport's content and framing requirements.", "followups": [["Does every notification need a response?", "No. Notifications differ from requests. Follow JSON-RPC and MCP semantics instead of returning ad hoc acknowledgments."], ["Is any JSON API an MCP implementation?", "No. Discovery, lifecycle, capability and transport behavior must also satisfy the implemented specification."]], "topic": "mcp", "lessonId": "mcp-jsonrpc"}, {"id": "mcp-schema", "tag": "Tool contracts", "prompt": "An MCP tool expects a positive invoice ID, but the model supplies free-form text. What should happen?", "options": ["Execute it because the model selected the tool.", "Convert the text into SQL automatically.", "Ignore the tool schema.", "Validate the input and reject or safely repair it before execution."], "correct": 3, "explanation": "Generated arguments are untrusted input. Validate schema, meaning, ownership and permissions before accessing a resource or performing an effect. A valid JSON object alone does not establish a valid business request.", "technical": "Use a typed input contract plus server-side business rules and parameterized queries. Bound repair attempts and return useful sanitized errors without leaking secrets or internal stack traces.", "followups": [["Can schema validation replace authorization?", "No. An ID can have the correct type and still refer to another tenant's object."], ["Why bound repair attempts?", "Repeated generation can consume resources or repeat deterministic errors. Fail clearly or clarify after the budget is exhausted."]], "topic": "mcp", "lessonId": "mcp-schema"}, {"id": "mcp-authn-authz", "tag": "Security", "prompt": "A user has a valid login token. What must the tool server still check?", "options": ["That the current identity is permitted to perform this action on this resource.", "Nothing; any signed-in user can access every resource.", "Only whether the model sounds confident.", "Whether the tool name contains the word secure."], "correct": 0, "explanation": "Authentication identifies a principal; authorization limits its actions and resources. A valid login token is not a universal access grant.", "technical": "Validate issuer/audience/expiry as appropriate, then scopes, tenant/resource ownership and current policy. Resolve trusted identity independently of model-generated tenant IDs.", "followups": [["Can the model choose a tenant_id?", "It can mention one, but trusted backend policy must resolve and authorize the actual scope."], ["Should permission be checked only at login?", "No. Check the relevant protected reads/effects and account for revocation at the required boundaries."]], "topic": "mcp", "lessonId": "mcp-authn-authz"}, {"id": "mcp-stdio-log", "tag": "Transport", "prompt": "A local stdio server prints debug text to stdout. Why can the client fail?", "options": ["Stdout is reserved for encrypted images.", "Non-protocol output corrupts the message stream; diagnostics belong on stderr.", "MCP never supports local servers.", "Debug logs automatically authorize the client."], "correct": 1, "explanation": "For the 2025-11-25 stdio transport, stdout carries protocol messages. Ordinary diagnostic output can break framing and parsing. Put diagnostics on stderr and keep secrets out of logs.", "technical": "Ensure libraries and startup code do not emit banners into stdout. Follow newline-delimited message framing and test the real subprocess entry point, not just a tool function in isolation.", "followups": [["Does any stderr output mean the server failed?", "No. Stderr can contain legitimate diagnostics. Inspect process status and protocol behavior too."], ["Why test the packaged entry point?", "Packaging and startup scripts can introduce logging, missing environment values or wrong working-directory assumptions."]], "topic": "mcp", "lessonId": "mcp-stdio-log"}, {"id": "mcp-http", "tag": "Transport", "prompt": "Which statement fits Streamable HTTP in the 2025-11-25 specification?", "options": ["Every response must be a WebSocket message.", "SSE is a separate mandatory service for every tool.", "It uses an MCP endpoint with HTTP POST/GET behavior and can return JSON or SSE under the protocol rules.", "It removes the need for origin validation."], "correct": 2, "explanation": "Streamable HTTP is not synonymous with WebSockets or an SSE-only endpoint. The selected specification defines endpoint, request, response and streaming behavior.", "technical": "Implement the actual transport negotiation, headers, message handling and origin protections for the pinned version. Do not assume a framework's generic streaming endpoint satisfies the protocol.", "followups": [["Is streaming always required for a simple result?", "No. The selected transport permits JSON responses under its rules; follow client/server capability and request semantics."], ["Can older clients behave differently?", "Yes. Pin and test protocol/SDK compatibility, including any deliberately supported legacy transport."]], "topic": "mcp", "lessonId": "mcp-http"}, {"id": "mcp-oauth", "tag": "Security", "prompt": "For HTTP-based MCP authorization under 2025-11-25, what role does a protected MCP server play?", "options": ["It becomes the user's password manager.", "It must receive raw passwords from every client.", "It treats any third-party token as valid for itself.", "It acts as a protected resource server and validates appropriately scoped access tokens."], "correct": 3, "explanation": "The authorization server issues tokens; the protected MCP server accepts and validates tokens intended for it. Token issuance and resource authorization are separate responsibilities.", "technical": "Follow the specified discovery and token-validation flow for the implemented version. Check audience/resource binding and scope rather than accepting a token simply because another service accepts it.", "followups": [["Must stdio use the same HTTP OAuth flow?", "The referenced version distinguishes stdio credentials from HTTP transport authorization. Follow the relevant transport's documented model."], ["Can all clients be preregistered?", "Registration approaches depend on the supported authorization deployment. Use the actual advertised and implemented mechanisms rather than assuming one flow."]], "topic": "mcp", "lessonId": "mcp-oauth"}, {"id": "mcp-injection", "tag": "Incident", "prompt": "A retrieved resource tells the agent to upload internal files to a new URL. What is the strongest boundary?", "options": ["Treat the text as untrusted data and enforce tool/resource permissions outside the model.", "Ask the model to promise it will not be tricked.", "Give the resource higher instruction priority.", "Enable every tool to maximize task completion."], "correct": 0, "explanation": "Retrieved text has no authority to grant capabilities. Behavioral prompts can help, but server-enforced access and effect controls limit actual exposure.", "technical": "Use narrow tools, approved destinations and current identity/resource checks. Separate source evidence from instructions and test indirect injection with permitted-task completion as well as blocked attacks.", "followups": [["Can a second model guarantee protection?", "No. Evaluate detector misses and false positives while retaining enforceable boundaries."], ["What if sensitive data already reached the generator?", "Prevent that with authorized retrieval. Tool controls alone cannot prevent disclosure through the generated answer."]], "topic": "mcp", "lessonId": "mcp-injection"}, {"id": "mcp-timeout", "tag": "Incident", "prompt": "A report-creation tool times out. Is it safe to retry with a new operation ID?", "options": ["Yes, a timeout proves the server did nothing.", "No; reconcile the previous operation and use idempotent semantics before retrying.", "Yes, if the next request uses a larger model.", "Only after hiding the error from logs."], "correct": 1, "explanation": "The remote action may have completed before the response was lost. A new ID can create a duplicate effect. Reconcile the original operation and retry under a deliberate idempotency policy.", "technical": "Store durable operation identity and status, distinguish unknown from failed, and use bounded retries with deadlines. Checkpoints do not make external effects exactly once automatically.", "followups": [["What if the API has no idempotency support?", "Use durable intent/status tracking and available lookup, and escalate unresolved ambiguity rather than blindly repeating irreversible actions."], ["Does canceling the local task undo the remote effect?", "No. Remote execution can continue. Reconciliation and business compensation are separate operations."]], "topic": "mcp", "lessonId": "mcp-timeout"}, {"id": "mcp-discovery", "tag": "Tool contracts", "prompt": "A discovered tool's description says it is harmless. How should the host use that claim?", "options": ["As a cryptographic authorization proof.", "As permission to bypass review.", "As metadata to consider, while enforcing trust and access separately.", "As proof the tool can never change state."], "correct": 2, "explanation": "Descriptions and annotations are not security enforcement. The actual server behavior, trust relationship and permission policy determine whether a tool is allowed.", "technical": "Maintain a trusted registry or approved connection policy where required, validate tool schemas and expose only necessary capabilities. Reassess changes to tool definitions and dependencies.", "followups": [["Can a tool description itself carry an injection?", "Yes. Treat third-party metadata as untrusted and avoid elevating it into policy."], ["Should a capability change be invisible to users?", "Not when it meaningfully changes permissions or effects. Apply the host's approval and trust policy."]], "topic": "mcp", "lessonId": "mcp-discovery"}, {"id": "mcp-resource-cache", "tag": "Security", "prompt": "Two tenants request the same resource URI string. Can one cached result serve both automatically?", "options": ["Yes, matching text always means matching permission.", "Yes, if the cache is encrypted.", "Yes, when the model asks politely.", "Only if the cache policy proves the result is shareable under both scopes and current permissions."], "correct": 3, "explanation": "Resource identifiers alone may not capture tenant, identity, personalization or policy version. A shared cache can cross an access boundary even when it is encrypted.", "technical": "Partition permission-sensitive cache entries and revalidate where required. Include relevant resource/version/freshness and identity scope, and test revocation behavior.", "followups": [["Does a hash of the URI solve access isolation?", "No. Hashing the same insufficient key retains the same logical collision between user scopes."], ["Can public resources be cached globally?", "Yes, when they are genuinely public and freshness/version rules are correct. The policy must establish that property."]], "topic": "mcp", "lessonId": "mcp-resource-cache"}, {"id": "mcp-error", "tag": "Development", "prompt": "A tool fails because a required field is absent. Which response is most useful?", "options": ["A sanitized, actionable validation error without executing the tool.", "A fabricated success result.", "An unrestricted production stack trace with credentials.", "An infinite automatic retry loop."], "correct": 0, "explanation": "The client needs enough information to correct the request or clarify the missing input. Do not claim success, leak internals or repeat a deterministic failure without a bound.", "technical": "Distinguish protocol failures, validation problems and application/tool errors according to the selected SDK and protocol. Keep correlation IDs for diagnosis without exposing secrets.", "followups": [["Should every tool error become a protocol error?", "No. Follow the relevant tool-result/error conventions; protocol validity and business failure are different concerns."], ["When should the host ask the user?", "When required information cannot be inferred safely from trusted state or permitted sources."]], "topic": "mcp", "lessonId": "mcp-error"}, {"id": "mcp-progress", "tag": "Production", "prompt": "A long-running MCP operation sends progress updates. What should monitoring still enforce?", "options": ["No limits as long as a heartbeat exists.", "Per-step and whole-operation deadlines, cancellation semantics and terminal outcomes.", "Only the total number of characters streamed.", "That all tools run in the browser."], "correct": 1, "explanation": "Progress is not completion. A healthy heartbeat can accompany an endless loop or stalled business task. Deadlines and terminal states keep the workflow bounded.", "technical": "Correlate operation/run IDs, record the last completed stage and distinguish waiting for approval from active execution. Cancellation must not be mistaken for guaranteed reversal of remote effects.", "followups": [["What if a legitimate job exceeds the deadline?", "Use an explicit async/status design with an appropriate budget, not an unbounded synchronous request."], ["Should retries reset the whole deadline?", "Not automatically. A total retry/time budget prevents work from running indefinitely through repeated attempts."]], "topic": "mcp", "lessonId": "mcp-progress"}, {"id": "mcp-revoke", "tag": "Incident", "prompt": "A user's access is revoked while an agent is paused. What happens on resume?", "options": ["The old checkpoint preserves access forever.", "The model decides whether revocation matters.", "Recheck current authorization before protected work and delivery.", "Send cached confidential content because retrieval happened earlier."], "correct": 2, "explanation": "A checkpoint preserves execution history, not permanent permission. Revalidate protected reads, effects and delivery under current policy, including saved evidence.", "technical": "Bind thread ownership to authenticated identity and track evidence provenance. Stop or quarantine state that no longer fits scope and audit the decision.", "followups": [["Can deleting the checkpoint undo a prior disclosure?", "No. Delivered responses, logs and caches have separate lifecycle controls."], ["Why check delivery as well as retrieval?", "Permission can change between retrieval and an eventual background result reaching the user."]], "topic": "mcp", "lessonId": "mcp-revoke"}, {"id": "mcp-rest", "tag": "Architecture", "prompt": "MCP versus REST: which comparison is most accurate?", "options": ["MCP makes all HTTP APIs obsolete.", "REST APIs can never back MCP tools.", "MCP is a model and REST is a database.", "MCP standardizes AI-facing capability interaction; a server can wrap existing APIs while preserving their access rules."], "correct": 3, "explanation": "MCP and ordinary HTTP APIs address different interface conventions. A server may adapt an existing service; the backend remains responsible for business correctness and permissions.", "technical": "Define an adapter boundary with typed inputs, stable errors, authentication propagation appropriate to each resource and versioned contracts. Do not blindly pass arbitrary credentials through a proxy.", "followups": [["Should every API endpoint be exposed as a tool?", "No. Expose the narrow task capabilities needed, with suitable permission and effect controls."], ["Does an adapter require rewriting the entire backend?", "No. It can wrap existing services behind a clear SDK/interface boundary if the contracts are compatible."]], "topic": "mcp", "lessonId": "mcp-rest"}, {"id": "mcp-version", "tag": "Development", "prompt": "A client works with one SDK version but fails after a server upgrade. What do you inspect first?", "options": ["Negotiated protocol/capabilities, transport behavior and changed input/output contracts.", "Only the GPU clock speed.", "Whether users memorized tool names.", "The number of decorative UI animations."], "correct": 0, "explanation": "Compatibility includes lifecycle, transport, capabilities and schemas. Pin supported versions and reproduce the actual client/server exchange before changing unrelated infrastructure.", "technical": "Keep a compatibility matrix, contract tests and safe rollout/rollback. Do not assume every example written for an older transport or authorization revision applies unchanged.", "followups": [["Should unknown capabilities be silently invented?", "No. Follow discovery/negotiation behavior and fail or degrade deliberately when a required capability is unavailable."], ["What should a regression test exercise?", "The packaged client/server lifecycle and real message contracts, including errors and authorization boundaries."]], "topic": "mcp", "lessonId": "mcp-version"}, {"id": "mcp-origin", "tag": "Security", "prompt": "Why validate Origin on a local HTTP MCP service?", "options": ["To identify the LLM's temperature.", "To help prevent malicious web origins from driving requests through DNS rebinding or cross-origin paths.", "To replace all access tokens permanently.", "To make stdout logs prettier."], "correct": 1, "explanation": "Origin checks are an important HTTP transport boundary, especially for local services. They complement authentication and safe binding; they do not replace authorization.", "technical": "Use trusted allowed origins, bind local services appropriately and follow the selected transport specification's required handling. Do not treat arbitrary Host/Origin values supplied by an attacker as proof of trust.", "followups": [["Should local services bind to every network interface by default?", "Not without a deliberate need and controls. Loopback limits exposure for local-only use."], ["Is Origin an authentication credential?", "No. It is one request-context signal; non-browser clients and application permissions require proper identity controls."]], "topic": "mcp", "lessonId": "mcp-origin"}, {"id": "mcp-test", "tag": "Testing", "prompt": "Which MCP test plan best reflects production readiness?", "options": ["Only verify the happy-path tool description.", "Only check that the server starts.", "Test contracts, denied access, malformed inputs, timeouts, recovery and compatibility.", "Use successful demos as the entire evaluation set."], "correct": 2, "explanation": "A production interface must handle permitted tasks and failure/security cases. A successful demonstration cannot prove resilience, scope isolation or compatibility.", "technical": "Include integration tests across the real transport, tenant/resource boundaries, bounded retries and ambiguous side effects. Track task success together with latency, unauthorized effects and recovery behavior.", "followups": [["What should an authorization test try?", "Access another user's resource, supply forged scope and attempt revoked access. The server must reject the actual read/effect."], ["Why test timeout recovery?", "It exposes duplicate effects and unknown outcomes that simple happy-path tests do not reveal."]], "topic": "mcp", "lessonId": "mcp-test"}, {"id": "mcp-least-privilege", "tag": "Architecture", "prompt": "An assistant needs to summarize invoices. Which tool design is preferable?", "options": ["A shell tool with unrestricted network and file access.", "A database administrator credential exposed to the model.", "A tool that runs arbitrary user-provided SQL as an owner.", "A narrow authorized invoice-read capability returning only required fields."], "correct": 3, "explanation": "Narrow capabilities reduce the consequences of model mistakes and injected instructions. The tool should enforce the current user's permitted invoices and minimize returned sensitive data.", "technical": "Prefer task-oriented read APIs with parameter validation, row/resource scope, audit and appropriate limits. Expand capability only for a demonstrated requirement with a matching permission model.", "followups": [["What if a new task needs writes?", "Add a separately scoped effectful capability with explicit business validation and any required approval, rather than broadening every read tool."], ["Can read-only tools still leak data?", "Yes. Unauthorized reading and overbroad responses can expose sensitive information even without modifying anything."]], "topic": "mcp", "lessonId": "mcp-least-privilege"}]}};
